def controlled_loop_start_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_start_packet(path: Path, *, code: str, label: str) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [controlled_loop_start_blocker(code, f"{label} could not be read as JSON", path=str(path), error=str(exc))]
    if not isinstance(packet, dict):
        return None, [controlled_loop_start_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_loop_start_type_blockers(
    packet: dict[str, Any],
    *,
    expected_packet: str,
    expected_schema: str,
    label: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if packet.get("schema_version") != expected_schema:
        blockers.append(
            controlled_loop_start_blocker(
                "controlled_start_packet_mismatch",
                f"{label} schema_version is invalid",
                expected=expected_schema,
                actual=packet.get("schema_version"),
            )
        )
    if packet.get("packet") != expected_packet:
        blockers.append(
            controlled_loop_start_blocker(
                "controlled_start_packet_mismatch",
                f"{label} packet is invalid",
                expected=expected_packet,
                actual=packet.get("packet"),
            )
        )
    return blockers


def controlled_loop_start_recommendation(blockers: list[dict[str, Any]]) -> str:
    if not blockers:
        return "plan_executor_invocation"
    codes = {blocker.get("code") for blocker in blockers}
    if "execution_start_task_mismatch" in codes:
        return "recreate_execution_start"
    if "loop_run_plan_not_ready" in codes:
        return "regenerate_loop_run_plan"
    if "execution_start_invalid" in codes:
        return "inspect_execution_start"
    if codes & {"loop_run_plan_evidence_missing", "execution_start_evidence_missing", "controlled_start_packet_mismatch"}:
        return "refresh_controlled_start_evidence"
    return "inspect_controlled_start_blockers"


def controlled_loop_start_side_effect_blockers(
    packet: dict[str, Any],
    *,
    flags: tuple[str, ...],
    expected_false: bool,
    code: str,
    label: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    for flag in flags:
        value = packet.get(flag)
        if expected_false:
            invalid = value is not False
        else:
            invalid = flag in packet and value is not False
        if invalid:
            blockers.append(
                controlled_loop_start_blocker(
                    code,
                    f"{label} must not report side-effect flag {flag}",
                    flag=flag,
                    actual=value,
                )
            )
    return blockers


def controlled_loop_start_active_epoch_blockers(
    root: Path,
    *,
    epoch_id: str,
    task_id: str,
    executor_task_checksum: str,
) -> list[dict[str, Any]]:
    try:
        active_epochs = read_active_epoch_records(root)
    except (OSError, RuntimeError, ValueError, json.JSONDecodeError) as exc:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                f"active epoch evidence could not be read: {exc}",
            )
        ]
    if len(active_epochs) != 1:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start must bind to exactly one active epoch",
                active_epoch_count=len(active_epochs),
            )
        ]
    path, active_epoch = active_epochs[0]
    blockers: list[dict[str, Any]] = []
    if active_epoch.get("id") != epoch_id:
        blockers.append(
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "active epoch id does not match execution start",
                expected=epoch_id,
                actual=active_epoch.get("id"),
                path=str(path),
            )
        )
    if active_epoch.get("status") != "ACTIVE":
        blockers.append(
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "active epoch status must be ACTIVE",
                actual=active_epoch.get("status"),
                path=str(path),
            )
        )
    tasks = active_epoch.get("tasks")
    if not isinstance(tasks, list):
        blockers.append(
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "active epoch tasks must be a list",
                path=str(path),
            )
        )
        return blockers
    matching_tasks = [task for task in tasks if isinstance(task, dict) and task.get("id") == task_id]
    if len(matching_tasks) != 1:
        blockers.append(
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "active epoch must contain exactly one matching executor task",
                task_id=task_id,
                matching_task_count=len(matching_tasks),
                path=str(path),
            )
        )
    elif matching_tasks[0].get("executor_task_checksum") != executor_task_checksum:
        blockers.append(
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "active epoch task checksum does not match loop run plan executor task",
                expected=executor_task_checksum,
                actual=matching_tasks[0].get("executor_task_checksum"),
                path=str(path),
            )
        )
    return blockers


def controlled_loop_start_audit_blockers(
    root: Path,
    execution_start: dict[str, Any],
    *,
    epoch_id: str,
    task_id: str,
    executor_task_checksum: str,
) -> list[dict[str, Any]]:
    audit_ref = execution_start.get("audit_record")
    if not isinstance(audit_ref, dict):
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start must include an audit_record reference",
            )
        ]
    expected_chain_index = audit_ref.get("chain_index")
    expected_event_hash = audit_ref.get("event_hash")
    if isinstance(expected_chain_index, bool) or not isinstance(expected_chain_index, int) or expected_chain_index < 1:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start audit_record chain_index is invalid",
                actual=expected_chain_index,
            )
        ]
    if not isinstance(expected_event_hash, str) or re.fullmatch(r"sha256:[0-9a-f]{64}", expected_event_hash) is None:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start audit_record event_hash is invalid",
                actual=expected_event_hash,
            )
        ]

    expected_payload = {key: value for key, value in execution_start.items() if key != "audit_record"}
    expected_payload_checksum = checksum_json(expected_payload)
    target = audit_events_path(root)
    try:
        lines = target.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start audit record is missing from the runtime audit log",
                path=str(target),
            )
        ]
    except OSError as exc:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                f"execution start audit log could not be read: {exc}",
                path=str(target),
            )
        ]

    matched_record = None
    for line_number, line in enumerate(lines, start=1):
        try:
            record = json.loads(line)
        except json.JSONDecodeError as exc:
            return [
                controlled_loop_start_blocker(
                    "execution_start_invalid",
                    f"execution start audit log contains malformed JSON: {exc}",
                    path=str(target),
                    line=line_number,
                )
            ]
        if not isinstance(record, dict):
            return [
                controlled_loop_start_blocker(
                    "execution_start_invalid",
                    "execution start audit log contains a non-object record",
                    path=str(target),
                    line=line_number,
                )
            ]
        if record.get("chain_index") == expected_chain_index and record.get("event_hash") == expected_event_hash:
            matched_record = record
            break

    if matched_record is None:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start audit record reference was not found in the runtime audit log",
                path=str(target),
                chain_index=expected_chain_index,
                event_hash=expected_event_hash,
            )
        ]

    if audit_event_hash(matched_record) != expected_event_hash:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start audit record event_hash does not match the recorded event",
                path=str(target),
                chain_index=expected_chain_index,
            )
        ]

    mismatches: dict[str, dict[str, Any]] = {}
    expected_values = {
        "event": "execution_start_decision",
        "valid": True,
        "epoch_started": True,
        "executor_started": False,
        "epoch_id": epoch_id,
        "task_id": task_id,
        "task_checksum": executor_task_checksum,
        "payload_checksum": expected_payload_checksum,
    }
    for field, expected in expected_values.items():
        actual = matched_record.get(field)
        if actual != expected:
            mismatches[field] = {"expected": expected, "actual": actual}
    if mismatches:
        return [
            controlled_loop_start_blocker(
                "execution_start_invalid",
                "execution start audit record does not match supplied execution-start evidence",
                path=str(target),
                chain_index=expected_chain_index,
                mismatches=mismatches,
            )
        ]
    return []


def controlled_loop_start_binding_blockers(
    root: Path,
    execution_start: dict[str, Any],
    *,
    epoch_id: str,
    task_id: str,
    executor_task_checksum: str,
) -> list[dict[str, Any]]:
    blockers = controlled_loop_start_active_epoch_blockers(
        root,
        epoch_id=epoch_id,
        task_id=task_id,
        executor_task_checksum=executor_task_checksum,
    )
    blockers.extend(
        controlled_loop_start_audit_blockers(
            root,
            execution_start,
            epoch_id=epoch_id,
            task_id=task_id,
            executor_task_checksum=executor_task_checksum,
        )
    )
    return blockers


def controlled_loop_start_command(args: argparse.Namespace) -> int:
    plan_path = Path(args.loop_run_plan_file)
    start_path = Path(args.execution_start_file)
    loop_run_plan, plan_blockers = read_controlled_loop_start_packet(
        plan_path,
        code="loop_run_plan_evidence_missing",
        label="loop run plan",
    )
    execution_start, start_blockers = read_controlled_loop_start_packet(
        start_path,
        code="execution_start_evidence_missing",
        label="execution start",
    )
    blockers = [*plan_blockers, *start_blockers]

    if isinstance(loop_run_plan, dict):
        blockers.extend(
            controlled_loop_start_type_blockers(
                loop_run_plan,
                expected_packet="loop_run_plan",
                expected_schema=LOOP_RUN_PLAN_SCHEMA_VERSION,
                label="loop run plan",
            )
        )
    if isinstance(execution_start, dict):
        blockers.extend(
            controlled_loop_start_type_blockers(
                execution_start,
                expected_packet="execution_start",
                expected_schema=EXECUTION_START_SCHEMA_VERSION,
                label="execution start",
            )
        )

    executor_task_checksum = None
    task_id = None
    epoch_id = None
    if not blockers and isinstance(loop_run_plan, dict) and isinstance(execution_start, dict):
        executor_task = loop_run_plan.get("executor_task")
        executor_task_checksum = loop_run_plan.get("executor_task_checksum")
        if not isinstance(executor_task, dict) or not isinstance(executor_task_checksum, str) or not executor_task_checksum.strip():
            blockers.append(
                controlled_loop_start_blocker(
                    "loop_run_plan_not_ready",
                    "loop run plan must include an executor task checksum",
                )
            )
        elif checksum_json(executor_task) != executor_task_checksum:
            blockers.append(
                controlled_loop_start_blocker(
                    "loop_run_plan_not_ready",
                    "loop run plan executor task checksum does not match embedded task",
                    expected=checksum_json(executor_task),
                    actual=executor_task_checksum,
                )
            )
        if isinstance(executor_task, dict):
            task_valid, task_reason = validate_executor_task_packet(executor_task)
            if not task_valid:
                blockers.append(
                    controlled_loop_start_blocker(
                        "loop_run_plan_not_ready",
                        f"loop run plan executor task is invalid: {task_reason}",
                    )
                )
        if loop_run_plan.get("recommended_next_action") != "request_operator_approval":
            blockers.append(
                controlled_loop_start_blocker(
                    "loop_run_plan_not_ready",
                    "loop run plan must be waiting for executor task operator approval",
                    actual=loop_run_plan.get("recommended_next_action"),
                )
            )
        blockers.extend(
            controlled_loop_start_side_effect_blockers(
                loop_run_plan,
                flags=CONTROLLED_LOOP_START_PLAN_NON_START_FLAGS,
                expected_false=True,
                code="loop_run_plan_not_ready",
                label="loop run plan",
            )
        )
        task = executor_task.get("task") if isinstance(executor_task, dict) and isinstance(executor_task.get("task"), dict) else {}
        task_id = task.get("id")
        if not isinstance(task_id, str) or not task_id.strip():
            blockers.append(
                controlled_loop_start_blocker(
                    "loop_run_plan_not_ready",
                    "loop run plan executor task id is required",
                )
            )
        plan_ready_for_anchor_check = (
            isinstance(executor_task, dict)
            and isinstance(executor_task_checksum, str)
            and bool(executor_task_checksum.strip())
            and isinstance(task_id, str)
            and bool(task_id.strip())
            and not any(blocker.get("code") == "loop_run_plan_not_ready" for blocker in blockers)
        )
        epoch_id = execution_start.get("epoch_id")
        execution_start_blocker_start = len(blockers)
        if execution_start.get("valid") is not True or execution_start.get("epoch_started") is not True:
            blockers.append(
                controlled_loop_start_blocker(
                    "execution_start_invalid",
                    "execution start evidence must be valid and epoch_started",
                )
            )
        if execution_start.get("approval_state") != "approved":
            blockers.append(
                controlled_loop_start_blocker(
                    "execution_start_invalid",
                    "execution start evidence must have approved approval_state",
                    actual=execution_start.get("approval_state"),
                )
            )
        blockers.extend(
            controlled_loop_start_side_effect_blockers(
                execution_start,
                flags=CONTROLLED_LOOP_START_EXECUTION_START_FORBIDDEN_TRUE_FLAGS,
                expected_false=False,
                code="execution_start_invalid",
                label="execution start",
            )
        )
        if execution_start.get("executor_started") is not False:
            blockers.append(
                controlled_loop_start_blocker(
                    "execution_start_invalid",
                    "execution start evidence must not start an executor",
                )
            )
        if not isinstance(epoch_id, str) or not epoch_id.strip():
            blockers.append(
                controlled_loop_start_blocker(
                    "execution_start_invalid",
                    "execution start evidence must include an epoch id",
                )
            )
        if plan_ready_for_anchor_check:
            execution_start_matches_plan = execution_start.get("task_checksum") == executor_task_checksum and execution_start.get("task_id") == task_id
            if not execution_start_matches_plan:
                blockers.append(
                    controlled_loop_start_blocker(
                        "execution_start_task_mismatch",
                        "execution start task anchor does not match loop run plan executor task",
                        expected_checksum=executor_task_checksum,
                        actual_checksum=execution_start.get("task_checksum"),
                        expected_task_id=task_id,
                        actual_task_id=execution_start.get("task_id"),
                    )
                )
            elif (
                isinstance(epoch_id, str)
                and epoch_id.strip()
                and not any(blocker.get("code") == "execution_start_invalid" for blocker in blockers[execution_start_blocker_start:])
            ):
                blockers.extend(
                    controlled_loop_start_binding_blockers(
                        args.root,
                        execution_start,
                        epoch_id=epoch_id,
                        task_id=task_id,
                        executor_task_checksum=executor_task_checksum,
                    )
                )

    valid = not blockers
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_START_SCHEMA_VERSION,
        "packet": "controlled_loop_start",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "controlled_start_status": "completed" if valid else "blocked",
        "reason": "loop run plan and execution start evidence match" if valid else "loop run plan and execution start evidence are incomplete or mismatched",
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": False if valid else True,
        "side_effects": [],
        "recommended_next_action": controlled_loop_start_recommendation(blockers),
        "files": {
            "loop_run_plan": str(plan_path),
            "execution_start": str(start_path),
        },
        "loop_run_plan": loop_run_plan if isinstance(loop_run_plan, dict) else None,
        "execution_start": execution_start if isinstance(execution_start, dict) else None,
        "loop_run_plan_checksum": checksum_json(loop_run_plan) if isinstance(loop_run_plan, dict) else None,
        "execution_start_checksum": checksum_json(execution_start) if isinstance(execution_start, dict) else None,
        "executor_task_checksum": executor_task_checksum,
        "task_id": task_id,
        "epoch_id": epoch_id,
        "blockers": blockers,
        "limitations": [
            "composes_existing_plan_and_execution_start_only",
            "does_not_continue_loop",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_INVOCATION_PLAN_SCHEMA_VERSION = "controlled-loop-invocation-plan.v1"
EXECUTOR_INVOCATION_READINESS_SCHEMA_VERSION = "executor-invocation-readiness.v1"
EXECUTOR_INVOCATION_PLAN_SCHEMA_VERSION = "executor-invocation-plan.v1"
CONTROLLED_LOOP_INVOCATION_FALSE_FLAGS = (
    "runner_started",
    "executor_started",
    "epoch_started",
    "pr_action_started",
    "github_write_started",
    "merge_started",
    "release_started",
    "package_publication_started",
    "role_assignment_started",
    "agent_scheduling_started",
    "loop_continuation_started",
)


def controlled_loop_invocation_plan_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_invocation_plan_packet(
    path: Path,
    *,
    code: str,
    label: str,
) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [
            controlled_loop_invocation_plan_blocker(
                code,
                f"{label} could not be read as JSON",
                path=str(path),
                error=str(exc),
            )
        ]
    if not isinstance(packet, dict):
        return None, [controlled_loop_invocation_plan_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_loop_invocation_plan_type_blockers(
    packet: dict[str, Any],
    *,
    expected_packet: str,
    expected_schema: str,
    label: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if packet.get("schema_version") != expected_schema:
        blockers.append(
            controlled_loop_invocation_plan_blocker(
                "controlled_invocation_packet_mismatch",
                f"{label} schema_version is invalid",
                expected=expected_schema,
                actual=packet.get("schema_version"),
            )
        )
    if packet.get("packet") != expected_packet:
        blockers.append(
            controlled_loop_invocation_plan_blocker(
                "controlled_invocation_packet_mismatch",
                f"{label} packet is invalid",
                expected=expected_packet,
                actual=packet.get("packet"),
            )
        )
    return blockers


def controlled_loop_invocation_plan_false_flag_blockers(
    packet: dict[str, Any],
    *,
    label: str,
    code: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    for flag in CONTROLLED_LOOP_INVOCATION_FALSE_FLAGS:
        if flag in packet and packet.get(flag) is not False:
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    code,
                    f"{label} must not report side-effect flag {flag}",
                    flag=flag,
                    actual=packet.get(flag),
                )
            )
    return blockers


def controlled_loop_invocation_plan_non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def controlled_loop_invocation_plan_recommendation(blockers: list[dict[str, Any]]) -> str:
    if not blockers:
        return "invoke_real_executor"
    codes = {blocker.get("code") for blocker in blockers}
    if codes & {"readiness_not_invocable", "controlled_start_readiness_mismatch"}:
        return "refresh_executor_invocation_readiness"
    if codes & {
        "invocation_plan_not_invocable",
        "invocation_plan_readiness_mismatch",
        "invocation_plan_target_checksum_mismatch",
    }:
        return "recreate_executor_invocation_plan"
    if "controlled_start_invalid" in codes:
        return "recreate_controlled_loop_start"
    if codes & {
        "controlled_loop_start_evidence_missing",
        "readiness_evidence_missing",
        "invocation_plan_evidence_missing",
        "controlled_invocation_packet_mismatch",
    }:
        return "refresh_controlled_invocation_evidence"
    return "inspect_controlled_invocation_blockers"


def controlled_loop_invocation_plan_command(args: argparse.Namespace) -> int:
    controlled_start_path = Path(args.controlled_loop_start_file)
    readiness_path = Path(args.readiness_file)
    invocation_plan_path = Path(args.invocation_plan_file)
    controlled_start, start_blockers = read_controlled_loop_invocation_plan_packet(
        controlled_start_path,
        code="controlled_loop_start_evidence_missing",
        label="controlled loop start",
    )
    readiness, readiness_blockers = read_controlled_loop_invocation_plan_packet(
        readiness_path,
        code="readiness_evidence_missing",
        label="executor invocation readiness",
    )
    invocation_plan, invocation_plan_blockers = read_controlled_loop_invocation_plan_packet(
        invocation_plan_path,
        code="invocation_plan_evidence_missing",
        label="executor invocation plan",
    )
    blockers = [*start_blockers, *readiness_blockers, *invocation_plan_blockers]

    if isinstance(controlled_start, dict):
        blockers.extend(
            controlled_loop_invocation_plan_type_blockers(
                controlled_start,
                expected_packet="controlled_loop_start",
                expected_schema=CONTROLLED_LOOP_START_SCHEMA_VERSION,
                label="controlled loop start",
            )
        )
    if isinstance(readiness, dict):
        blockers.extend(
            controlled_loop_invocation_plan_type_blockers(
                readiness,
                expected_packet="executor_invocation_readiness",
                expected_schema=EXECUTOR_INVOCATION_READINESS_SCHEMA_VERSION,
                label="executor invocation readiness",
            )
        )
    if isinstance(invocation_plan, dict):
        blockers.extend(
            controlled_loop_invocation_plan_type_blockers(
                invocation_plan,
                expected_packet="executor_invocation_plan",
                expected_schema=EXECUTOR_INVOCATION_PLAN_SCHEMA_VERSION,
                label="executor invocation plan",
            )
        )

    task_id = None
    epoch_id = None
    target_checksum = None
    if isinstance(controlled_start, dict):
        task_id = controlled_start.get("task_id")
        epoch_id = controlled_start.get("epoch_id")
    if isinstance(invocation_plan, dict):
        target_checksum = invocation_plan.get("target_checksum")

    if not blockers and isinstance(controlled_start, dict) and isinstance(readiness, dict) and isinstance(invocation_plan, dict):
        if (
            controlled_start.get("read_only") is not True
            or controlled_start.get("valid") is not True
            or controlled_start.get("controlled_start_status") != "completed"
            or controlled_start.get("recommended_next_action") != "plan_executor_invocation"
            or controlled_start.get("side_effects") != []
        ):
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "controlled_start_invalid",
                    "controlled loop start evidence must be completed and ready for invocation planning",
                    actual_status=controlled_start.get("controlled_start_status"),
                    actual_next_action=controlled_start.get("recommended_next_action"),
                )
            )
        blockers.extend(
            controlled_loop_invocation_plan_false_flag_blockers(
                controlled_start,
                label="controlled loop start",
                code="controlled_start_invalid",
            )
        )

        if (
            readiness.get("read_only") is not True
            or readiness.get("valid") is not True
            or readiness.get("executor_invocation_ready") is not True
            or readiness.get("side_effects") != []
            or readiness.get("executor_started") is not False
        ):
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "readiness_not_invocable",
                    "readiness evidence must be valid, read-only, and executor-ready",
                    actual_next_action=readiness.get("recommended_next_action"),
                )
            )
        blockers.extend(
            controlled_loop_invocation_plan_false_flag_blockers(
                readiness,
                label="executor invocation readiness",
                code="readiness_not_invocable",
            )
        )

        if (
            invocation_plan.get("read_only") is not True
            or invocation_plan.get("valid") is not True
            or invocation_plan.get("executor_invocation_planned") is not True
            or invocation_plan.get("side_effects") != []
            or invocation_plan.get("executor_started") is not False
            or invocation_plan.get("recommended_next_action") != "invoke_real_executor"
        ):
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "invocation_plan_not_invocable",
                    "invocation plan evidence must be valid, read-only, and ready for real executor invocation",
                    actual_next_action=invocation_plan.get("recommended_next_action"),
                )
            )
        blockers.extend(
            controlled_loop_invocation_plan_false_flag_blockers(
                invocation_plan,
                label="executor invocation plan",
                code="invocation_plan_not_invocable",
            )
        )

        controlled_start_task_checksum = controlled_start.get("executor_task_checksum")
        readiness_task = readiness.get("task") if isinstance(readiness.get("task"), dict) else {}
        readiness_epoch = readiness.get("active_epoch") if isinstance(readiness.get("active_epoch"), dict) else {}
        readiness_task_checksum = readiness_task.get("checksum")
        readiness_task_id = readiness_task.get("id")
        controlled_start_execution = controlled_start.get("execution_start") if isinstance(controlled_start.get("execution_start"), dict) else {}
        controlled_start_files = controlled_start.get("files") if isinstance(controlled_start.get("files"), dict) else {}
        controlled_start_execution_file = controlled_start_files.get("execution_start")
        controlled_start_execution_context = controlled_start_path
        if controlled_loop_invocation_plan_non_empty_string(controlled_start_execution_file):
            resolved_start_file = controlled_tick_context_path(controlled_start_path, controlled_start_execution_file)
            if isinstance(resolved_start_file, Path):
                controlled_start_execution_context = resolved_start_file
        controlled_start_task_file = controlled_start_execution.get("task_file")
        readiness_task_file = readiness_task.get("file")
        if (
            not controlled_loop_invocation_plan_non_empty_string(controlled_start_task_checksum)
            or not controlled_loop_invocation_plan_non_empty_string(readiness_task_checksum)
            or not controlled_loop_invocation_plan_non_empty_string(task_id)
            or not controlled_loop_invocation_plan_non_empty_string(readiness_task_id)
            or readiness_task_checksum != controlled_start_task_checksum
            or readiness_task_id != task_id
        ):
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "controlled_start_readiness_mismatch",
                    "readiness task anchor does not match controlled loop start",
                    expected_task_id=task_id,
                    actual_task_id=readiness_task_id,
                    expected_checksum=controlled_start_task_checksum,
                    actual_checksum=readiness_task_checksum,
                )
            )
        if (
            not controlled_loop_invocation_plan_non_empty_string(controlled_start_task_file)
            or not controlled_loop_invocation_plan_non_empty_string(readiness_task_file)
            or not _closeout_paths_match(
                controlled_tick_context_path(controlled_start_execution_context, controlled_start_task_file),
                controlled_tick_context_path(readiness_path, readiness_task_file),
            )
        ):
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "controlled_start_readiness_mismatch",
                    "readiness task file does not match controlled loop start task file",
                    expected_task_file=controlled_start_task_file,
                    actual_task_file=readiness_task_file,
                )
            )
        readiness_epoch_id = readiness_epoch.get("id")
        if (
            not controlled_loop_invocation_plan_non_empty_string(epoch_id)
            or not controlled_loop_invocation_plan_non_empty_string(readiness_epoch_id)
            or readiness_epoch_id != epoch_id
        ):
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "controlled_start_readiness_mismatch",
                    "readiness active epoch does not match controlled loop start",
                    expected_epoch_id=epoch_id,
                    actual_epoch_id=readiness_epoch_id,
                )
            )

        readiness_checksum = checksum_json(readiness)
        plan_readiness = invocation_plan.get("readiness") if isinstance(invocation_plan.get("readiness"), dict) else {}
        if plan_readiness.get("checksum") != readiness_checksum:
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "invocation_plan_readiness_mismatch",
                    "invocation plan readiness checksum does not match supplied readiness",
                    expected=readiness_checksum,
                    actual=plan_readiness.get("checksum"),
                )
            )
        plan_readiness_file = plan_readiness.get("file")
        if not isinstance(plan_readiness_file, str) or not plan_readiness_file.strip():
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "invocation_plan_readiness_mismatch",
                    "invocation plan readiness file is required",
                    expected=str(readiness_path),
                    actual=plan_readiness_file,
                )
            )
        elif not controlled_tick_context_paths_match(invocation_plan_path, plan_readiness_file, readiness_path):
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "invocation_plan_readiness_mismatch",
                    "invocation plan readiness file does not match supplied readiness file",
                    expected=str(readiness_path),
                    actual=plan_readiness_file,
                )
            )

        target = invocation_plan.get("target")
        if not isinstance(target, dict) or not isinstance(target_checksum, str) or not target_checksum.strip():
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "invocation_plan_not_invocable",
                    "invocation plan target and checksum are required",
                )
            )
        elif checksum_json(target) != target_checksum:
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "invocation_plan_target_checksum_mismatch",
                    "invocation plan target checksum does not match target payload",
                    expected=checksum_json(target),
                    actual=target_checksum,
                )
            )
        elif target.get("readiness_checksum") != readiness_checksum:
            blockers.append(
                controlled_loop_invocation_plan_blocker(
                    "invocation_plan_readiness_mismatch",
                    "invocation target readiness checksum does not match supplied readiness",
                    expected=readiness_checksum,
                    actual=target.get("readiness_checksum"),
                )
            )

    valid = not blockers
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_INVOCATION_PLAN_SCHEMA_VERSION,
        "packet": "controlled_loop_invocation_plan",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "controlled_invocation_plan_status": "completed" if valid else "blocked",
        "reason": "controlled loop invocation plan evidence matches" if valid else "controlled loop invocation plan evidence is incomplete or mismatched",
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": False if valid else True,
        "side_effects": [],
        "recommended_next_action": controlled_loop_invocation_plan_recommendation(blockers),
        "files": {
            "controlled_loop_start": str(controlled_start_path),
            "readiness": str(readiness_path),
            "invocation_plan": str(invocation_plan_path),
        },
        "controlled_loop_start": controlled_start if isinstance(controlled_start, dict) else None,
        "readiness": readiness if isinstance(readiness, dict) else None,
        "invocation_plan": invocation_plan if isinstance(invocation_plan, dict) else None,
        "controlled_loop_start_checksum": checksum_json(controlled_start) if isinstance(controlled_start, dict) else None,
        "readiness_checksum": checksum_json(readiness) if isinstance(readiness, dict) else None,
        "invocation_plan_checksum": checksum_json(invocation_plan) if isinstance(invocation_plan, dict) else None,
        "task_id": task_id,
        "epoch_id": epoch_id,
        "target_checksum": target_checksum,
        "blockers": blockers,
        "limitations": [
            "composes_existing_start_readiness_and_invocation_plan_only",
            "does_not_continue_loop",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_REAL_INVOCATION_SCHEMA_VERSION = "controlled-loop-real-invocation.v1"


def controlled_loop_real_invocation_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_real_invocation_packet(
    path: Path,
    *,
    code: str,
    label: str,
) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [
            controlled_loop_real_invocation_blocker(
                code,
                f"{label} could not be read as JSON",
                path=str(path),
                error=str(exc),
            )
        ]
    if not isinstance(packet, dict):
        return None, [controlled_loop_real_invocation_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_loop_real_invocation_type_blockers(
    packet: dict[str, Any],
    *,
    expected_packet: str,
    expected_schema: str,
    label: str,
    code: str = "controlled_real_invocation_packet_mismatch",
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if packet.get("schema_version") != expected_schema:
        blockers.append(
            controlled_loop_real_invocation_blocker(
                code,
                f"{label} schema_version is invalid",
                expected=expected_schema,
                actual=packet.get("schema_version"),
            )
        )
    if packet.get("packet") != expected_packet:
        blockers.append(
            controlled_loop_real_invocation_blocker(
                code,
                f"{label} packet is invalid",
                expected=expected_packet,
                actual=packet.get("packet"),
            )
        )
    return blockers


def controlled_loop_real_invocation_recommendation(blockers: list[dict[str, Any]]) -> str:
    if not blockers:
        return "closeout_executor_result"
    codes = {blocker.get("code") for blocker in blockers}
    if codes & {
        "controlled_invocation_plan_evidence_missing",
        "controlled_invocation_plan_invalid",
        "controlled_invocation_plan_mismatch",
        "controlled_invocation_plan_target_mismatch",
        "controlled_invocation_plan_packet_mismatch",
    }:
        return "refresh_controlled_loop_invocation_plan"
    return "inspect_real_invocation_evidence"


def controlled_loop_real_invocation_non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def controlled_loop_real_invocation_audit_blockers(
    root: Path,
    real_invocation: dict[str, Any],
    real_invocation_path: Path,
) -> list[dict[str, Any]]:
    audit_replay = replay_audit_log(root)
    if audit_replay.get("valid") is not True:
        audit_chain = real_invocation.get("audit_chain") if isinstance(real_invocation.get("audit_chain"), dict) else {}
        return [
            controlled_loop_real_invocation_blocker(
                "real_invocation_audit_mismatch",
                "current audit chain is not valid for controlled real-invocation closeout",
                invocation_chain_head=audit_chain.get("chain_head"),
                current_chain_head=audit_replay.get("chain_head"),
                audit_blockers=audit_replay.get("blockers"),
            )
        ]
    blockers: list[dict[str, Any]] = []
    invocation_id = real_invocation.get("invocation_id")
    if controlled_loop_real_invocation_non_empty_string(invocation_id):
        try:
            canonical_path = real_executor_invocation_path(root, invocation_id)
        except ValueError as exc:
            return [
                controlled_loop_real_invocation_blocker(
                    "real_invocation_identity_missing",
                    "real invocation invocation_id is invalid",
                    actual=invocation_id,
                    error=str(exc),
                )
            ]
        if not _closeout_paths_match(real_invocation_path, canonical_path):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "real_invocation_record_mismatch",
                    "real invocation file must be the canonical runtime invocation record path",
                    expected=str(canonical_path),
                    actual=str(real_invocation_path),
                )
            )
    for blocker in _closeout_real_invocation_audit_blockers(root, real_invocation, real_invocation_path):
        source_code = blocker.get("code")
        code = "real_invocation_record_mismatch" if source_code == "invocation_checksum_mismatch" else "real_invocation_audit_mismatch"
        blockers.append(
            controlled_loop_real_invocation_blocker(
                code,
                blocker.get("message", "real invocation audit anchor does not match"),
                **{key: value for key, value in blocker.items() if key not in {"code", "message"}},
            )
        )
    return blockers


def controlled_loop_real_invocation_command(args: argparse.Namespace) -> int:
    controlled_plan_path = Path(args.controlled_invocation_plan_file)
    real_invocation_path = Path(args.real_invocation_file)
    controlled_plan, controlled_plan_blockers = read_controlled_loop_real_invocation_packet(
        controlled_plan_path,
        code="controlled_invocation_plan_evidence_missing",
        label="controlled invocation plan",
    )
    real_invocation, real_invocation_blockers = read_controlled_loop_real_invocation_packet(
        real_invocation_path,
        code="real_invocation_evidence_missing",
        label="real executor invocation",
    )
    blockers = [*controlled_plan_blockers, *real_invocation_blockers]

    if isinstance(controlled_plan, dict):
        blockers.extend(
            controlled_loop_real_invocation_type_blockers(
                controlled_plan,
                expected_packet="controlled_loop_invocation_plan",
                expected_schema=CONTROLLED_LOOP_INVOCATION_PLAN_SCHEMA_VERSION,
                label="controlled invocation plan",
                code="controlled_invocation_plan_packet_mismatch",
            )
        )
    if isinstance(real_invocation, dict):
        blockers.extend(
            controlled_loop_real_invocation_type_blockers(
                real_invocation,
                expected_packet="real_executor_invocation",
                expected_schema=REAL_EXECUTOR_INVOCATION_SCHEMA_VERSION,
                label="real executor invocation",
                code="real_invocation_packet_mismatch",
            )
        )

    invocation_plan: dict[str, Any] | None = None
    result_evidence: dict[str, Any] | None = None
    result_evidence_checksum: str | None = None
    invocation_plan_checksum: str | None = None
    task_id = None
    epoch_id = None
    target_checksum = None

    if not blockers and isinstance(controlled_plan, dict) and isinstance(real_invocation, dict):
        if (
            controlled_plan.get("read_only") is not True
            or controlled_plan.get("valid") is not True
            or controlled_plan.get("controlled_invocation_plan_status") != "completed"
            or controlled_plan.get("recommended_next_action") != "invoke_real_executor"
            or controlled_plan.get("side_effects") != []
            or controlled_plan.get("executor_started") is not False
        ):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "controlled_invocation_plan_invalid",
                    "controlled invocation plan must be valid, read-only, and ready for real executor invocation",
                    actual_status=controlled_plan.get("controlled_invocation_plan_status"),
                    actual_next_action=controlled_plan.get("recommended_next_action"),
                )
            )
        for flag_blocker in controlled_loop_invocation_plan_false_flag_blockers(
            controlled_plan,
            label="controlled invocation plan",
            code="controlled_invocation_plan_invalid",
        ):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    flag_blocker["code"],
                    flag_blocker["message"],
                    **{key: value for key, value in flag_blocker.items() if key not in {"code", "message"}},
                )
            )

        nested_plan = controlled_plan.get("invocation_plan")
        if not isinstance(nested_plan, dict):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "controlled_invocation_plan_invalid",
                    "controlled invocation plan must embed the executor invocation plan",
                )
            )
        else:
            invocation_plan = nested_plan
            blockers.extend(
                controlled_loop_real_invocation_type_blockers(
                    invocation_plan,
                    expected_packet="executor_invocation_plan",
                    expected_schema=EXECUTOR_INVOCATION_PLAN_SCHEMA_VERSION,
                    label="embedded invocation plan",
                    code="controlled_invocation_plan_invalid",
                )
            )
            invocation_plan_checksum = checksum_json(invocation_plan)
            task_id = controlled_plan.get("task_id")
            epoch_id = controlled_plan.get("epoch_id")
            target_checksum = invocation_plan.get("target_checksum")
            if controlled_plan.get("invocation_plan_checksum") != invocation_plan_checksum:
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "controlled_invocation_plan_mismatch",
                        "controlled invocation plan checksum does not match embedded invocation plan",
                        expected=invocation_plan_checksum,
                        actual=controlled_plan.get("invocation_plan_checksum"),
                    )
                )
            if controlled_plan.get("target_checksum") != target_checksum:
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "controlled_invocation_plan_target_mismatch",
                        "controlled invocation plan target checksum does not match embedded invocation plan",
                        expected=target_checksum,
                        actual=controlled_plan.get("target_checksum"),
                    )
                )
            target = invocation_plan.get("target")
            if not isinstance(target, dict) or not controlled_loop_real_invocation_non_empty_string(target_checksum):
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "controlled_invocation_plan_invalid",
                        "embedded invocation plan target and target checksum are required",
                    )
                )
            elif checksum_json(target) != target_checksum:
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "controlled_invocation_plan_target_mismatch",
                        "embedded invocation plan target checksum does not match target payload",
                        expected=checksum_json(target),
                        actual=target_checksum,
                    )
                )

        if (
            real_invocation.get("valid") is not True
            or real_invocation.get("executor_started") is not True
            or real_invocation.get("timed_out") is not False
            or real_invocation.get("recommended_next_action") != "bind_real_executor_closeout"
        ):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "real_invocation_invalid",
                    "real invocation evidence must be valid, executor-started, and ready for closeout binding",
                    actual_next_action=real_invocation.get("recommended_next_action"),
                )
            )
        if not controlled_loop_real_invocation_non_empty_string(real_invocation.get("invocation_id")):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "real_invocation_identity_missing",
                    "real invocation invocation_id is required",
                )
            )
        if real_invocation.get("closeout_status") != "pending":
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "real_invocation_closeout_not_pending",
                    "real invocation closeout_status must be pending before controlled closeout composition",
                    actual=real_invocation.get("closeout_status"),
                )
            )

        if invocation_plan is not None:
            if real_invocation.get("plan_checksum") != invocation_plan_checksum:
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "real_invocation_plan_mismatch",
                        "real invocation plan checksum does not match controlled invocation plan",
                        expected=invocation_plan_checksum,
                        actual=real_invocation.get("plan_checksum"),
                    )
                )
            if real_invocation.get("plan_target_checksum") != target_checksum:
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "real_invocation_plan_mismatch",
                        "real invocation target checksum does not match controlled invocation plan target",
                        expected=target_checksum,
                        actual=real_invocation.get("plan_target_checksum"),
                    )
                )
            controlled_files = controlled_plan.get("files") if isinstance(controlled_plan.get("files"), dict) else {}
            controlled_invocation_plan_file = controlled_files.get("invocation_plan")
            if not controlled_tick_context_paths_match(
                controlled_plan_path,
                controlled_invocation_plan_file,
                controlled_tick_invocation_path(real_invocation, real_invocation.get("plan_file")),
            ):
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "real_invocation_plan_mismatch",
                        "real invocation plan_file does not match controlled invocation plan input file",
                        expected=controlled_invocation_plan_file,
                        actual=real_invocation.get("plan_file"),
                    )
                )
            target = invocation_plan.get("target") if isinstance(invocation_plan.get("target"), dict) else {}
            expected_result_path = target.get("expected_result_path")
            if not _closeout_paths_match(
                controlled_tick_invocation_path(real_invocation, real_invocation.get("result_file")),
                expected_result_path,
            ):
                blockers.append(
                    controlled_loop_real_invocation_blocker(
                        "real_invocation_result_mismatch",
                        "real invocation result_file does not match invocation target expected_result_path",
                        expected=expected_result_path,
                        actual=real_invocation.get("result_file"),
                    )
                )

        if not _closeout_paths_match(
            controlled_tick_invocation_path(real_invocation, real_invocation.get("record_file")),
            real_invocation_path,
        ):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "real_invocation_record_mismatch",
                    "real invocation record_file does not match supplied real invocation file",
                    expected=str(real_invocation_path),
                    actual=real_invocation.get("record_file"),
                )
            )
        blockers.extend(controlled_loop_real_invocation_audit_blockers(args.root, real_invocation, real_invocation_path))

        result_file_value = real_invocation.get("result_file")
        result_path = controlled_tick_invocation_path(real_invocation, result_file_value)
        if not isinstance(result_path, Path):
            blockers.append(
                controlled_loop_real_invocation_blocker(
                    "real_invocation_result_mismatch",
                    "real invocation result_file is required",
                    actual=result_file_value,
                )
            )
        elif not blockers:
            loaded_result, result_blockers = read_controlled_loop_real_invocation_packet(
                result_path,
                code="real_invocation_result_mismatch",
                label="real invocation result",
            )
            blockers.extend(result_blockers)
            if isinstance(loaded_result, dict):
                result_evidence = loaded_result
                result_evidence_checksum = checksum_json(result_evidence)
                if real_invocation.get("result_evidence_checksum") != result_evidence_checksum:
                    blockers.append(
                        controlled_loop_real_invocation_blocker(
                            "real_invocation_result_mismatch",
                            "real invocation result checksum does not match result file",
                            expected=result_evidence_checksum,
                            actual=real_invocation.get("result_evidence_checksum"),
                        )
                    )

    valid = not blockers
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_REAL_INVOCATION_SCHEMA_VERSION,
        "packet": "controlled_loop_real_invocation",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "controlled_real_invocation_status": "completed" if valid else "blocked",
        "reason": "controlled real invocation evidence matches" if valid else "controlled real invocation evidence is incomplete or mismatched",
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": False if valid else True,
        "side_effects": [],
        "recommended_next_action": controlled_loop_real_invocation_recommendation(blockers),
        "files": {
            "controlled_invocation_plan": str(controlled_plan_path),
            "real_invocation": str(real_invocation_path),
            "result": str(real_invocation.get("result_file")) if isinstance(real_invocation, dict) else None,
        },
        "controlled_invocation_plan": controlled_plan if isinstance(controlled_plan, dict) else None,
        "real_invocation": real_invocation if isinstance(real_invocation, dict) else None,
        "result_evidence": result_evidence,
        "controlled_invocation_plan_checksum": checksum_json(controlled_plan) if isinstance(controlled_plan, dict) else None,
        "invocation_plan_checksum": invocation_plan_checksum,
        "real_invocation_checksum": checksum_json(real_invocation) if isinstance(real_invocation, dict) else None,
        "result_evidence_checksum": result_evidence_checksum,
        "task_id": task_id,
        "epoch_id": epoch_id,
        "target_checksum": target_checksum,
        "blockers": blockers,
        "limitations": [
            "composes_existing_controlled_invocation_plan_and_real_invocation_only",
            "does_not_continue_loop",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
            "does_not_append_audit",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_CLOSEOUT_SCHEMA_VERSION = "controlled-loop-closeout.v1"
CONTROLLED_LOOP_CLOSEOUT_TERMINAL_STATUSES = {"completed", "failed"}


def controlled_loop_closeout_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_closeout_packet(
    path: Path,
    *,
    code: str,
    label: str,
) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [
            controlled_loop_closeout_blocker(
                code,
                f"{label} could not be read as JSON",
                path=str(path),
                error=str(exc),
            )
        ]
    if not isinstance(packet, dict):
        return None, [controlled_loop_closeout_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_loop_closeout_type_blockers(
    packet: dict[str, Any],
    *,
    expected_packet: str,
    expected_schema: str,
    label: str,
    code: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if packet.get("schema_version") != expected_schema:
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} schema_version is invalid",
                expected=expected_schema,
                actual=packet.get("schema_version"),
            )
        )
    if packet.get("packet") != expected_packet:
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} packet is invalid",
                expected=expected_packet,
                actual=packet.get("packet"),
            )
        )
    return blockers


def controlled_loop_closeout_recommendation(blockers: list[dict[str, Any]]) -> str:
    if not blockers:
        return "controlled_loop_tick"
    codes = {blocker.get("code") for blocker in blockers}
    if codes & {
        "controlled_real_invocation_evidence_missing",
        "controlled_real_invocation_packet_mismatch",
        "controlled_real_invocation_invalid",
    }:
        return "refresh_controlled_loop_real_invocation"
    return "inspect_closeout_evidence"


def controlled_loop_closeout_context_path(context_file: Path, value: Any) -> Any:
    if not isinstance(value, str) or not value.strip():
        return value
    path = Path(value).expanduser()
    if not path.is_absolute():
        path = context_file.parent / path
    return path


def controlled_loop_closeout_runtime_anchor_path(
    root: Path,
    context_file: Path,
    value: Any,
    canonical_path: Path | None,
) -> Any:
    context_path = controlled_loop_closeout_context_path(context_file, value)
    if canonical_path is None or not isinstance(value, str) or not value.strip():
        return context_path
    raw_path = Path(value).expanduser()
    if raw_path.is_absolute():
        return context_path
    root_relative_path = root / raw_path
    if _closeout_paths_match(root_relative_path, canonical_path):
        return root_relative_path
    return context_path


def controlled_loop_closeout_false_flag_blockers(
    packet: dict[str, Any],
    *,
    label: str,
    code: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    for flag in CONTROLLED_LOOP_INVOCATION_FALSE_FLAGS:
        if flag in packet and packet.get(flag) is not False:
            blockers.append(
                controlled_loop_closeout_blocker(
                    code,
                    f"{label} must not report side-effect flag {flag}",
                    flag=flag,
                    actual=packet.get(flag),
                )
            )
    return blockers


def controlled_loop_closeout_controlled_graph_blockers(
    controlled: dict[str, Any],
    pre_invocation: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    controlled_plan = controlled.get("controlled_invocation_plan")
    result_evidence = controlled.get("result_evidence")

    if not isinstance(controlled_plan, dict):
        blockers.append(
            controlled_loop_closeout_blocker(
                "controlled_real_invocation_invalid",
                "controlled real invocation must embed the controlled invocation plan",
            )
        )
    else:
        blockers.extend(
            controlled_loop_closeout_type_blockers(
                controlled_plan,
                expected_packet="controlled_loop_invocation_plan",
                expected_schema=CONTROLLED_LOOP_INVOCATION_PLAN_SCHEMA_VERSION,
                label="embedded controlled invocation plan",
                code="controlled_real_invocation_invalid",
            )
        )
        controlled_plan_checksum = checksum_json(controlled_plan)
        if controlled.get("controlled_invocation_plan_checksum") != controlled_plan_checksum:
            blockers.append(
                controlled_loop_closeout_blocker(
                    "controlled_real_invocation_invalid",
                    "controlled real invocation controlled_invocation_plan_checksum does not match embedded plan",
                    expected=controlled_plan_checksum,
                    actual=controlled.get("controlled_invocation_plan_checksum"),
                )
            )
        for field in ("task_id", "epoch_id", "target_checksum", "invocation_plan_checksum"):
            if controlled.get(field) != controlled_plan.get(field):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        f"controlled real invocation {field} does not match embedded controlled invocation plan",
                        expected=controlled_plan.get(field),
                        actual=controlled.get(field),
                    )
                )

        invocation_plan = controlled_plan.get("invocation_plan")
        if not isinstance(invocation_plan, dict):
            blockers.append(
                controlled_loop_closeout_blocker(
                    "controlled_real_invocation_invalid",
                    "embedded controlled invocation plan must embed the executor invocation plan",
                )
            )
        else:
            blockers.extend(
                controlled_loop_closeout_type_blockers(
                    invocation_plan,
                    expected_packet="executor_invocation_plan",
                    expected_schema=EXECUTOR_INVOCATION_PLAN_SCHEMA_VERSION,
                    label="embedded executor invocation plan",
                    code="controlled_real_invocation_invalid",
                )
            )
            invocation_plan_checksum = checksum_json(invocation_plan)
            if controlled.get("invocation_plan_checksum") != invocation_plan_checksum:
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "controlled real invocation invocation_plan_checksum does not match embedded executor invocation plan",
                        expected=invocation_plan_checksum,
                        actual=controlled.get("invocation_plan_checksum"),
                    )
                )
            if controlled_plan.get("invocation_plan_checksum") != invocation_plan_checksum:
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "embedded controlled invocation plan invocation_plan_checksum does not match embedded executor invocation plan",
                        expected=invocation_plan_checksum,
                        actual=controlled_plan.get("invocation_plan_checksum"),
                    )
                )
            if controlled.get("target_checksum") != invocation_plan.get("target_checksum"):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "controlled real invocation target_checksum does not match embedded executor invocation plan",
                        expected=invocation_plan.get("target_checksum"),
                        actual=controlled.get("target_checksum"),
                    )
                )
            target = invocation_plan.get("target")
            target_checksum = invocation_plan.get("target_checksum")
            if not isinstance(target, dict) or not controlled_loop_real_invocation_non_empty_string(target_checksum):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "embedded executor invocation plan target and target checksum are required",
                    )
                )
            elif checksum_json(target) != target_checksum:
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "embedded executor invocation plan target_checksum does not match target payload",
                        expected=checksum_json(target),
                        actual=target_checksum,
                    )
                )

    if not isinstance(result_evidence, dict):
        blockers.append(
            controlled_loop_closeout_blocker(
                "controlled_real_invocation_invalid",
                "controlled real invocation must embed result evidence",
            )
        )
    else:
        result_evidence_checksum = checksum_json(result_evidence)
        if controlled.get("result_evidence_checksum") != result_evidence_checksum:
            blockers.append(
                controlled_loop_closeout_blocker(
                    "controlled_real_invocation_invalid",
                    "controlled real invocation result_evidence_checksum does not match embedded result evidence",
                    expected=result_evidence_checksum,
                    actual=controlled.get("result_evidence_checksum"),
                )
            )
        for field in ("task_id", "epoch_id"):
            if field in result_evidence and controlled.get(field) != result_evidence.get(field):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        f"controlled real invocation {field} does not match embedded result evidence",
                        expected=result_evidence.get(field),
                        actual=controlled.get(field),
                    )
                )

    if pre_invocation is not None:
        expected_pre_invocation_fields = {
            "plan_checksum": controlled.get("invocation_plan_checksum"),
            "plan_target_checksum": controlled.get("target_checksum"),
            "result_evidence_checksum": controlled.get("result_evidence_checksum"),
        }
        for field, expected in expected_pre_invocation_fields.items():
            if expected is not None and pre_invocation.get(field) != expected:
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        f"controlled real invocation embedded invocation {field} does not match controlled anchors",
                        expected=expected,
                        actual=pre_invocation.get(field),
                    )
                )

    return blockers


def controlled_loop_closeout_audit_line_blockers(
    root: Path,
    context_file: Path,
    audit_ref: Any,
    *,
    expected_event: str,
    code: str,
    label: str,
    expected_checksums: dict[str, str | None],
) -> list[dict[str, Any]]:
    if not isinstance(audit_ref, dict):
        return [controlled_loop_closeout_blocker(code, f"{label} audit reference is required")]
    audit_path_value = audit_ref.get("path")
    if not controlled_loop_real_invocation_non_empty_string(audit_path_value):
        return [controlled_loop_closeout_blocker(code, f"{label} audit reference path is required")]
    audit_path = controlled_loop_closeout_context_path(context_file, audit_path_value)
    if not isinstance(audit_path, Path):
        return [controlled_loop_closeout_blocker(code, f"{label} audit reference path is required")]
    expected_audit_path = audit_events_path(root)
    blockers: list[dict[str, Any]] = []
    if not _closeout_paths_match(audit_path, expected_audit_path):
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} audit reference path does not match runtime audit log",
                expected=str(expected_audit_path),
                actual=str(audit_path),
            )
        )
        return blockers
    chain_index = audit_ref.get("chain_index")
    if isinstance(chain_index, bool) or not isinstance(chain_index, int) or chain_index < 1:
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} audit reference chain_index must be a positive integer",
                actual=chain_index,
            )
        )
        return blockers
    try:
        lines = audit_path.read_text(encoding="utf-8").splitlines()
        record = json.loads(lines[chain_index - 1])
    except (IndexError, OSError, ValueError, json.JSONDecodeError) as exc:
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} audit reference line could not be read",
                line=chain_index,
                error=str(exc),
            )
        )
        return blockers
    if not isinstance(record, dict):
        blockers.append(controlled_loop_closeout_blocker(code, f"{label} audit reference line must be a JSON object", line=chain_index))
        return blockers
    event, audit_blockers = validate_audit_record(record, chain_index)
    for blocker in audit_blockers:
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} audit reference line is invalid",
                nested_blocker=blocker,
                line=chain_index,
            )
        )
    if event != expected_event:
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} audit reference event is invalid",
                expected=expected_event,
                actual=event,
                line=chain_index,
            )
        )
    for field in ("event", "recorded_at", "audit_chain_version", "chain_index", "previous_event_hash", "event_hash"):
        if record.get(field) != audit_ref.get(field):
            blockers.append(
                controlled_loop_closeout_blocker(
                    code,
                    f"{label} audit reference {field} does not match audit line",
                    expected=audit_ref.get(field),
                    actual=record.get(field),
                    line=chain_index,
                )
            )
    if record.get("event_hash") != audit_event_hash(record):
        blockers.append(
            controlled_loop_closeout_blocker(
                code,
                f"{label} audit reference event_hash does not match audit line payload",
                expected=record.get("event_hash"),
                actual=audit_event_hash(record),
                line=chain_index,
            )
        )
    for field, expected in expected_checksums.items():
        if expected is not None and record.get(field) != expected:
            blockers.append(
                controlled_loop_closeout_blocker(
                    code,
                    f"{label} audit reference {field} does not match evidence",
                    expected=expected,
                    actual=record.get(field),
                    line=chain_index,
                )
            )
    return blockers


def controlled_loop_closeout_command(args: argparse.Namespace) -> int:
    controlled_path = Path(args.controlled_real_invocation_file)
    closeout_path = Path(args.closeout_file)
    controlled, controlled_blockers = read_controlled_loop_closeout_packet(
        controlled_path,
        code="controlled_real_invocation_evidence_missing",
        label="controlled real invocation",
    )
    closeout, closeout_blockers = read_controlled_loop_closeout_packet(
        closeout_path,
        code="closeout_evidence_missing",
        label="executor closeout",
    )
    blockers = [*controlled_blockers, *closeout_blockers]

    if isinstance(controlled, dict):
        blockers.extend(
            controlled_loop_closeout_type_blockers(
                controlled,
                expected_packet="controlled_loop_real_invocation",
                expected_schema=CONTROLLED_LOOP_REAL_INVOCATION_SCHEMA_VERSION,
                label="controlled real invocation",
                code="controlled_real_invocation_packet_mismatch",
            )
        )
    if isinstance(closeout, dict):
        blockers.extend(
            controlled_loop_closeout_type_blockers(
                closeout,
                expected_packet="executor_epoch_closeout",
                expected_schema=EXECUTOR_EPOCH_CLOSEOUT_SCHEMA_VERSION,
                label="executor closeout",
                code="closeout_packet_mismatch",
            )
        )

    controlled_real_invocation_checksum = checksum_json(controlled) if isinstance(controlled, dict) else None
    closeout_checksum = checksum_json(closeout) if isinstance(closeout, dict) else None
    pre_invocation: dict[str, Any] | None = None
    updated_invocation: dict[str, Any] | None = None
    updated_invocation_checksum: str | None = None
    pre_invocation_checksum: str | None = None
    epoch_closeout_checksum: str | None = None
    task_id = None
    epoch_id = None
    closeout_status = closeout.get("closeout_status") if isinstance(closeout, dict) else None
    real_invocation_file_output: str | None = None
    safe_invocation_path_verified = False

    if not blockers and isinstance(controlled, dict) and isinstance(closeout, dict):
        if (
            controlled.get("read_only") is not True
            or controlled.get("valid") is not True
            or controlled.get("controlled_real_invocation_status") != "completed"
            or controlled.get("recommended_next_action") != "closeout_executor_result"
            or controlled.get("side_effects") != []
            or controlled.get("executor_started") is not False
        ):
            blockers.append(
                controlled_loop_closeout_blocker(
                    "controlled_real_invocation_invalid",
                    "controlled real invocation must be valid, read-only, and ready for closeout",
                    actual_status=controlled.get("controlled_real_invocation_status"),
                    actual_next_action=controlled.get("recommended_next_action"),
                )
            )
        blockers.extend(
            controlled_loop_closeout_false_flag_blockers(
                controlled,
                label="controlled real invocation",
                code="controlled_real_invocation_invalid",
            )
        )

        pre_invocation_value = controlled.get("real_invocation")
        if not isinstance(pre_invocation_value, dict):
            blockers.append(
                controlled_loop_closeout_blocker(
                    "controlled_real_invocation_invalid",
                    "controlled real invocation must embed the pre-closeout real invocation record",
                )
            )
        else:
            pre_invocation = pre_invocation_value
            pre_invocation_checksum = checksum_json(pre_invocation)
            if controlled.get("real_invocation_checksum") != pre_invocation_checksum:
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "controlled real invocation checksum does not match embedded real invocation",
                        expected=pre_invocation_checksum,
                        actual=controlled.get("real_invocation_checksum"),
                    )
                )

        blockers.extend(controlled_loop_closeout_controlled_graph_blockers(controlled, pre_invocation))

        if closeout.get("valid") is not True:
            blockers.append(controlled_loop_closeout_blocker("closeout_invalid", "executor closeout evidence must be valid"))
        if closeout.get("closeout_status") not in CONTROLLED_LOOP_CLOSEOUT_TERMINAL_STATUSES:
            blockers.append(
                controlled_loop_closeout_blocker(
                    "closeout_not_terminal",
                    "executor closeout evidence must be terminal completed or failed",
                    actual=closeout.get("closeout_status"),
                )
            )
        closeout_invocation = closeout.get("real_invocation") if isinstance(closeout.get("real_invocation"), dict) else {}
        if not closeout_invocation:
            blockers.append(
                controlled_loop_closeout_blocker(
                    "closeout_invocation_mismatch",
                    "executor closeout must reference the bound real invocation",
                )
            )

        controlled_files = controlled.get("files") if isinstance(controlled.get("files"), dict) else {}
        controlled_invocation_path = controlled_loop_closeout_context_path(controlled_path, controlled_files.get("real_invocation"))
        closeout_invocation_path = controlled_loop_closeout_context_path(closeout_path, closeout_invocation.get("path"))
        if not isinstance(controlled_invocation_path, Path):
            blockers.append(
                controlled_loop_closeout_blocker(
                    "controlled_real_invocation_invalid",
                    "controlled real invocation real_invocation file anchor is required",
                    actual=controlled_files.get("real_invocation"),
                )
            )
        invocation_path_matches = False

        if pre_invocation is not None:
            pre_record_path = controlled_tick_invocation_path(pre_invocation, pre_invocation.get("record_file"))
            pre_record_path_matches = False
            if not isinstance(pre_record_path, Path):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "embedded real invocation record_file is required",
                        actual=pre_invocation.get("record_file"),
                    )
                )
            invocation_id = pre_invocation.get("invocation_id")
            canonical_path_matches = False
            canonical_invocation_path: Path | None = None
            if not controlled_loop_real_invocation_non_empty_string(invocation_id):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "controlled_real_invocation_invalid",
                        "embedded real invocation invocation_id is required",
                        actual=invocation_id,
                    )
                )
            else:
                try:
                    canonical_invocation_path = real_executor_invocation_path(args.root, invocation_id)
                except ValueError as exc:
                    blockers.append(
                        controlled_loop_closeout_blocker(
                            "controlled_real_invocation_invalid",
                            "embedded real invocation invocation_id is invalid",
                            actual=invocation_id,
                            error=str(exc),
                        )
                    )
                else:
                    controlled_invocation_path = controlled_loop_closeout_runtime_anchor_path(
                        args.root,
                        controlled_path,
                        controlled_files.get("real_invocation"),
                        canonical_invocation_path,
                    )
                    closeout_invocation_path = controlled_loop_closeout_runtime_anchor_path(
                        args.root,
                        closeout_path,
                        closeout_invocation.get("path"),
                        canonical_invocation_path,
                    )
                    invocation_path_matches = isinstance(controlled_invocation_path, Path) and _closeout_paths_match(
                        closeout_invocation_path,
                        controlled_invocation_path,
                    )
                    if isinstance(pre_record_path, Path):
                        pre_record_path_matches = isinstance(controlled_invocation_path, Path) and _closeout_paths_match(
                            controlled_invocation_path,
                            pre_record_path,
                        )
                        if not pre_record_path_matches:
                            blockers.append(
                                controlled_loop_closeout_blocker(
                                    "controlled_real_invocation_invalid",
                                    "controlled real invocation file anchor does not match embedded real invocation record_file",
                                    expected=str(pre_record_path),
                                    actual=str(controlled_invocation_path)
                                    if isinstance(controlled_invocation_path, Path)
                                    else controlled_files.get("real_invocation"),
                                )
                            )
                    if not invocation_path_matches:
                        blockers.append(
                            controlled_loop_closeout_blocker(
                                "closeout_invocation_mismatch",
                                "executor closeout real invocation path does not match controlled real invocation input",
                                expected=str(controlled_invocation_path)
                                if isinstance(controlled_invocation_path, Path)
                                else controlled_files.get("real_invocation"),
                                actual=closeout_invocation.get("path"),
                            )
                        )
                    canonical_path_matches = isinstance(controlled_invocation_path, Path) and _closeout_paths_match(
                        controlled_invocation_path,
                        canonical_invocation_path,
                    )
                    if not canonical_path_matches:
                        blockers.append(
                            controlled_loop_closeout_blocker(
                                "controlled_real_invocation_invalid",
                                "controlled real invocation file anchor does not match canonical runtime invocation path",
                                expected=str(canonical_invocation_path),
                                actual=str(controlled_invocation_path)
                                if isinstance(controlled_invocation_path, Path)
                                else controlled_files.get("real_invocation"),
                            )
                        )
            safe_invocation_path_verified = invocation_path_matches and pre_record_path_matches and canonical_path_matches
            if safe_invocation_path_verified and isinstance(controlled_invocation_path, Path):
                real_invocation_file_output = str(controlled_invocation_path)
            if closeout_invocation.get("before_checksum") != pre_invocation_checksum:
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "closeout_invocation_mismatch",
                        "executor closeout real invocation before_checksum does not match controlled real invocation",
                        expected=pre_invocation_checksum,
                        actual=closeout_invocation.get("before_checksum"),
                    )
                )
            if closeout_invocation.get("invocation_id") != pre_invocation.get("invocation_id"):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "closeout_invocation_mismatch",
                        "executor closeout real invocation id does not match controlled real invocation",
                        expected=pre_invocation.get("invocation_id"),
                        actual=closeout_invocation.get("invocation_id"),
                    )
                )
            if closeout.get("epoch_id") != controlled.get("epoch_id"):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "closeout_epoch_mismatch",
                        "executor closeout epoch does not match controlled real invocation",
                        expected=controlled.get("epoch_id"),
                        actual=closeout.get("epoch_id"),
                    )
                )
            if closeout.get("result_file") and not _closeout_paths_match(
                controlled_tick_invocation_path(pre_invocation, pre_invocation.get("result_file")),
                controlled_loop_closeout_context_path(closeout_path, closeout.get("result_file")),
            ):
                blockers.append(
                    controlled_loop_closeout_blocker(
                        "closeout_result_mismatch",
                        "executor closeout result_file does not match controlled real invocation result file",
                        expected=pre_invocation.get("result_file"),
                        actual=closeout.get("result_file"),
                    )
                )

        closeout_core = {
            key: value
            for key, value in closeout.items()
            if key not in {"audit_record", "run_record", "real_invocation"}
        }
        epoch_closeout_checksum = checksum_json(closeout_core)
        if closeout_invocation.get("epoch_closeout_checksum") != epoch_closeout_checksum:
            blockers.append(
                controlled_loop_closeout_blocker(
                    "closeout_invocation_mismatch",
                    "executor closeout real invocation epoch_closeout_checksum does not match closeout evidence",
                    expected=epoch_closeout_checksum,
                    actual=closeout_invocation.get("epoch_closeout_checksum"),
                )
            )

        audit_replay = replay_audit_log(args.root)
        if audit_replay.get("valid") is not True:
            blockers.append(
                controlled_loop_closeout_blocker(
                    "closeout_audit_mismatch",
                    "current audit chain is not valid for controlled closeout composition",
                    current_chain_head=audit_replay.get("chain_head"),
                    audit_blockers=audit_replay.get("blockers"),
                )
            )

        if safe_invocation_path_verified and not any(blocker.get("code") == "controlled_real_invocation_invalid" for blocker in blockers):
            loaded_invocation, invocation_blockers = read_controlled_loop_closeout_packet(
                controlled_invocation_path,
                code="real_invocation_evidence_missing",
                label="updated real invocation",
            )
            blockers.extend(invocation_blockers)
            if isinstance(loaded_invocation, dict):
                updated_invocation = loaded_invocation
                updated_invocation_checksum = checksum_json(updated_invocation)
                blockers.extend(
                    controlled_loop_closeout_type_blockers(
                        updated_invocation,
                        expected_packet="real_executor_invocation",
                        expected_schema=REAL_EXECUTOR_INVOCATION_SCHEMA_VERSION,
                        label="updated real invocation",
                        code="real_invocation_packet_mismatch",
                    )
                )
                if closeout_invocation.get("after_checksum") != updated_invocation_checksum:
                    blockers.append(
                        controlled_loop_closeout_blocker(
                            "closeout_invocation_mismatch",
                            "executor closeout real invocation after_checksum does not match updated invocation record",
                            expected=updated_invocation_checksum,
                            actual=closeout_invocation.get("after_checksum"),
                        )
                    )
                if closeout_invocation.get("closeout_status") != closeout.get("closeout_status"):
                    blockers.append(
                        controlled_loop_closeout_blocker(
                            "closeout_invocation_mismatch",
                            "executor closeout real invocation closeout_status does not match closeout evidence",
                            expected=closeout.get("closeout_status"),
                            actual=closeout_invocation.get("closeout_status"),
                        )
                    )
                expected_updated_fields = {
                    "invocation_id": closeout_invocation.get("invocation_id"),
                    "closeout_status": closeout.get("closeout_status"),
                    "epoch_id": controlled.get("epoch_id"),
                    "epoch_status": closeout.get("epoch_status"),
                    "epoch_closeout_checksum": epoch_closeout_checksum,
                    "result_evidence_checksum": controlled.get("result_evidence_checksum"),
                    "validation_packet_checksum": checksum_json(closeout.get("validation")) if isinstance(closeout.get("validation"), dict) else None,
                    "snapshot_after_checksum": closeout.get("snapshot_after_checksum"),
                }
                for field, expected in expected_updated_fields.items():
                    if expected is not None and updated_invocation.get(field) != expected:
                        blockers.append(
                            controlled_loop_closeout_blocker(
                                "real_invocation_closeout_mismatch",
                                f"updated real invocation {field} does not match closeout evidence",
                                expected=expected,
                                actual=updated_invocation.get(field),
                            )
                        )
                closeout_rewritten_fields = {
                    "closeout_status",
                    "epoch_id",
                    "epoch_status",
                    "epoch_closeout_checksum",
                    "task_file",
                    "result_evidence_checksum",
                    "validation_packet_checksum",
                    "snapshot_after_checksum",
                    "updated_at",
                }
                for field, expected in pre_invocation.items():
                    if field in closeout_rewritten_fields:
                        continue
                    if updated_invocation.get(field) != expected:
                        blockers.append(
                            controlled_loop_closeout_blocker(
                                "real_invocation_closeout_mismatch",
                                f"updated real invocation immutable field {field} changed during closeout",
                                expected=expected,
                                actual=updated_invocation.get(field),
                            )
                        )
                for field in updated_invocation:
                    if field not in pre_invocation and field not in closeout_rewritten_fields:
                        blockers.append(
                            controlled_loop_closeout_blocker(
                                "real_invocation_closeout_mismatch",
                                f"updated real invocation unexpected field {field} appeared during closeout",
                                actual=updated_invocation.get(field),
                            )
                        )
                if not _closeout_paths_match(
                    controlled_tick_invocation_path(updated_invocation, updated_invocation.get("record_file")),
                    controlled_invocation_path,
                ):
                    blockers.append(
                        controlled_loop_closeout_blocker(
                            "real_invocation_closeout_mismatch",
                            "updated real invocation record_file does not match controlled real invocation input",
                            expected=str(controlled_invocation_path),
                            actual=updated_invocation.get("record_file"),
                        )
                    )
                if closeout.get("task_file") and not _closeout_paths_match(
                    controlled_tick_invocation_path(updated_invocation, updated_invocation.get("task_file")),
                    controlled_loop_closeout_context_path(closeout_path, closeout.get("task_file")),
                ):
                    blockers.append(
                        controlled_loop_closeout_blocker(
                            "real_invocation_closeout_mismatch",
                            "updated real invocation task_file does not match closeout evidence",
                            expected=closeout.get("task_file"),
                            actual=updated_invocation.get("task_file"),
                        )
                    )

        if audit_replay.get("valid") is True:
            blockers.extend(
                controlled_loop_closeout_audit_line_blockers(
                    args.root,
                    closeout_path,
                    closeout.get("audit_record"),
                    expected_event="executor_epoch_closeout",
                    code="closeout_audit_mismatch",
                    label="executor closeout",
                    expected_checksums={
                        "payload_checksum": checksum_json({key: value for key, value in closeout.items() if key != "audit_record"}),
                        "task_packet_checksum": closeout.get("task_checksum"),
                        "result_evidence_checksum": controlled.get("result_evidence_checksum"),
                        "snapshot_after_checksum": closeout.get("snapshot_after_checksum"),
                    },
                )
            )
            if closeout_invocation:
                invocation_update_payload_checksum = (
                    checksum_json(
                        {
                            "action": "update_real_executor_invocation_closeout",
                            "reason": "real executor invocation closeout status updated",
                            "invocation_record_file": str(controlled_invocation_path),
                            "invocation_record_checksum": updated_invocation_checksum,
                        }
                    )
                    if updated_invocation_checksum is not None and isinstance(controlled_invocation_path, Path)
                    else None
                )
                blockers.extend(
                    controlled_loop_closeout_audit_line_blockers(
                        args.root,
                        closeout_path,
                        closeout_invocation.get("audit_record"),
                        expected_event="real_executor_invocation_record",
                        code="real_invocation_audit_mismatch",
                        label="real invocation closeout update",
                        expected_checksums={
                            "payload_checksum": invocation_update_payload_checksum,
                            "invocation_record_checksum": updated_invocation_checksum,
                            "plan_checksum": controlled.get("invocation_plan_checksum"),
                            "plan_target_checksum": controlled.get("target_checksum"),
                            "result_evidence_checksum": controlled.get("result_evidence_checksum"),
                            "validation_packet_checksum": checksum_json(closeout.get("validation")) if isinstance(closeout.get("validation"), dict) else None,
                            "snapshot_after_checksum": closeout.get("snapshot_after_checksum"),
                            "epoch_closeout_checksum": epoch_closeout_checksum,
                        },
                    )
                )

        task_id = controlled.get("task_id")
        epoch_id = controlled.get("epoch_id")

    valid = not blockers
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_CLOSEOUT_SCHEMA_VERSION,
        "packet": "controlled_loop_closeout",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "controlled_closeout_status": "completed" if valid else "blocked",
        "reason": "controlled closeout evidence matches" if valid else "controlled closeout evidence is incomplete or mismatched",
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": False if valid else True,
        "side_effects": [],
        "recommended_next_action": controlled_loop_closeout_recommendation(blockers),
        "files": {
            "controlled_real_invocation": str(controlled_path),
            "closeout": str(closeout_path),
            "real_invocation": real_invocation_file_output,
        },
        "controlled_real_invocation": controlled if isinstance(controlled, dict) else None,
        "closeout": closeout if isinstance(closeout, dict) else None,
        "real_invocation": updated_invocation,
        "controlled_real_invocation_checksum": controlled_real_invocation_checksum,
        "closeout_checksum": closeout_checksum,
        "real_invocation_before_checksum": pre_invocation_checksum,
        "real_invocation_after_checksum": updated_invocation_checksum,
        "epoch_closeout_checksum": epoch_closeout_checksum,
        "task_id": task_id,
        "epoch_id": epoch_id,
        "closeout_status": closeout_status,
        "blockers": blockers,
        "limitations": [
            "composes_existing_controlled_real_invocation_and_closeout_only",
            "does_not_continue_loop",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_close_epoch",
            "does_not_rewrite_invocation_or_closeout_records",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
            "does_not_append_audit",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_TICK_SCHEMA_VERSION = "controlled-loop-tick.v1"
CONTROLLED_LOOP_TICK_TERMINAL_CLOSEOUT_STATUSES = {"completed", "failed"}


def controlled_loop_tick_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def controlled_tick_non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def read_controlled_tick_packet(path: Path, *, code: str, label: str) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [controlled_loop_tick_blocker(code, f"{label} could not be read as JSON", path=str(path), error=str(exc))]
    if not isinstance(packet, dict):
        return None, [controlled_loop_tick_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_tick_step(name: str, path: Path, packet: Any, status: str, blockers: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "name": name,
        "status": status,
        "file": str(path),
        "checksum": checksum_json(packet) if isinstance(packet, dict) else None,
        "blocker_codes": [blocker["code"] for blocker in blockers],
    }


def controlled_tick_packet_type_blockers(packet: dict[str, Any], *, label: str, expected_packet: str, expected_schema: str | None = None) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if expected_schema is not None and packet.get("schema_version") != expected_schema:
        blockers.append(
            controlled_loop_tick_blocker(
                "controlled_tick_packet_mismatch",
                f"{label} schema_version is invalid",
                expected=expected_schema,
                actual=packet.get("schema_version"),
            )
        )
    if packet.get("packet") != expected_packet:
        blockers.append(
            controlled_loop_tick_blocker(
                "controlled_tick_packet_mismatch",
                f"{label} packet is invalid",
                expected=expected_packet,
                actual=packet.get("packet"),
            )
        )
    return blockers


def controlled_tick_paths_match(left: Any, right: Path) -> bool:
    if isinstance(left, str) and left.strip():
        return _closeout_paths_match(left, right)
    return False


def controlled_tick_context_paths_match(context_file: Path, left: Any, right: Path) -> bool:
    return _closeout_paths_match(controlled_tick_context_path(context_file, left), right)


def controlled_tick_context_path(context_file: Path, value: Any) -> Any:
    if not isinstance(value, str) or not value.strip():
        return value
    path = Path(value).expanduser()
    if not path.is_absolute():
        path = context_file.parent / path
    return path


def controlled_tick_invocation_path(invocation: dict[str, Any], value: Any) -> Any:
    if not isinstance(value, str) or not value.strip():
        return value
    return _invocation_context_path(invocation, value)


def controlled_loop_tick_command(args: argparse.Namespace) -> int:
    packet_inputs = {
        "loop_tick": Path(args.loop_tick_file),
        "task": Path(args.task_file),
        "execution_start": Path(args.execution_start_file),
        "readiness": Path(args.readiness_file),
        "invocation_plan": Path(args.invocation_plan_file),
        "real_invocation": Path(args.real_invocation_file),
        "result": Path(args.result_file),
        "snapshot_after": Path(args.snapshot_after_file),
        "closeout": Path(args.closeout_file),
    }
    optional_git_pr_plan = Path(args.git_pr_plan_file) if args.git_pr_plan_file else None
    packets: dict[str, Any] = {}
    blockers: list[dict[str, Any]] = []
    read_codes = {
        "loop_tick": "loop_tick_evidence_missing",
        "task": "task_evidence_missing",
        "execution_start": "execution_start_evidence_missing",
        "readiness": "readiness_evidence_missing",
        "invocation_plan": "invocation_plan_evidence_missing",
        "real_invocation": "real_invocation_evidence_missing",
        "result": "result_evidence_missing",
        "snapshot_after": "snapshot_after_evidence_missing",
        "closeout": "closeout_evidence_missing",
    }
    step_blockers: dict[str, list[dict[str, Any]]] = {}
    for name, path in packet_inputs.items():
        packet, packet_blockers = read_controlled_tick_packet(
            path,
            code=read_codes[name],
            label=name.replace("_", " "),
        )
        packets[name] = packet
        step_blockers[name] = list(packet_blockers)
        blockers.extend(packet_blockers)

    if optional_git_pr_plan is not None:
        packet, packet_blockers = read_controlled_tick_packet(
            optional_git_pr_plan,
            code="git_pr_plan_evidence_missing",
            label="git pr plan",
        )
        packets["git_pr_plan"] = packet
        step_blockers["git_pr_plan"] = list(packet_blockers)
        blockers.extend(packet_blockers)

    if not blockers:
        loop_tick = packets["loop_tick"]
        task_packet = packets["task"]
        execution_start = packets["execution_start"]
        readiness = packets["readiness"]
        invocation_plan = packets["invocation_plan"]
        real_invocation = packets["real_invocation"]
        result_evidence = packets["result"]
        snapshot_after = packets["snapshot_after"]
        closeout = packets["closeout"]
        git_pr_plan = packets.get("git_pr_plan")

        expected_types = {
            "loop_tick": ("loop_tick", None),
            "execution_start": ("execution_start", EXECUTION_START_SCHEMA_VERSION),
            "readiness": ("executor_invocation_readiness", EXECUTOR_INVOCATION_READINESS_SCHEMA_VERSION),
            "invocation_plan": ("executor_invocation_plan", EXECUTOR_INVOCATION_PLAN_SCHEMA_VERSION),
            "real_invocation": ("real_executor_invocation", REAL_EXECUTOR_INVOCATION_SCHEMA_VERSION),
            "result": ("executor_result", "generic-executor-result.v1"),
            "closeout": ("executor_epoch_closeout", EXECUTOR_EPOCH_CLOSEOUT_SCHEMA_VERSION),
        }
        for name, (expected_packet, expected_schema) in expected_types.items():
            packet_blockers = controlled_tick_packet_type_blockers(
                packets[name],
                label=name.replace("_", " "),
                expected_packet=expected_packet,
                expected_schema=expected_schema,
            )
            step_blockers[name].extend(packet_blockers)
            blockers.extend(packet_blockers)
        if git_pr_plan is not None:
            packet_blockers = controlled_tick_packet_type_blockers(
                git_pr_plan,
                label="git pr plan",
                expected_packet="git_pr_plan",
                expected_schema="git-pr-plan.v1",
            )
            packet_blockers.extend(validate_git_pr_plan_dry_run_packet(git_pr_plan))
            step_blockers["git_pr_plan"].extend(packet_blockers)
            blockers.extend(packet_blockers)

        valid_task, invalid_task_reason = validate_executor_task_packet(task_packet)
        if not valid_task:
            blocker = controlled_loop_tick_blocker("executor_task_invalid", invalid_task_reason)
            step_blockers["task"].append(blocker)
            blockers.append(blocker)
        task_checksum = checksum_json(task_packet)
        task = task_packet.get("task") if isinstance(task_packet.get("task"), dict) else {}
        repo = task_packet.get("repo") if isinstance(task_packet.get("repo"), dict) else {}
        task_id = task.get("id")
        epoch_id = execution_start.get("epoch_id")

        loop_task = loop_tick.get("executor_task") if isinstance(loop_tick.get("executor_task"), dict) else {}
        if not controlled_tick_non_empty_string(loop_tick.get("tick_id")):
            blocker = controlled_loop_tick_blocker("loop_tick_identity_missing", "loop tick tick_id is required")
            step_blockers["loop_tick"].append(blocker)
            blockers.append(blocker)
        if checksum_json(loop_task) != task_checksum:
            blocker = controlled_loop_tick_blocker(
                "loop_tick_task_mismatch",
                "loop tick executor_task does not match the supplied task packet",
                expected=task_checksum,
                actual=checksum_json(loop_task),
            )
            step_blockers["loop_tick"].append(blocker)
            blockers.append(blocker)
        if loop_tick.get("recommended_next_action") != "approve_executor_task":
            blocker = controlled_loop_tick_blocker(
                "loop_tick_not_ready",
                "loop tick must have emitted an executor task for approval",
                actual=loop_tick.get("recommended_next_action"),
            )
            step_blockers["loop_tick"].append(blocker)
            blockers.append(blocker)
        if execution_start.get("valid") is not True or execution_start.get("epoch_started") is not True:
            blocker = controlled_loop_tick_blocker("execution_start_invalid", "execution start evidence must be valid and epoch_started")
            step_blockers["execution_start"].append(blocker)
            blockers.append(blocker)
        if not controlled_tick_non_empty_string(epoch_id):
            blocker = controlled_loop_tick_blocker("execution_start_invalid", "execution start epoch_id is required")
            step_blockers["execution_start"].append(blocker)
            blockers.append(blocker)
        if execution_start.get("executor_started") is not False:
            blocker = controlled_loop_tick_blocker("execution_start_invalid", "execution start must not start an executor")
            step_blockers["execution_start"].append(blocker)
            blockers.append(blocker)
        if execution_start.get("task_checksum") != task_checksum or execution_start.get("task_id") != task_id:
            blocker = controlled_loop_tick_blocker("execution_start_task_mismatch", "execution start task anchor does not match task packet")
            step_blockers["execution_start"].append(blocker)
            blockers.append(blocker)
        if "task_file" in execution_start and not controlled_tick_context_paths_match(packet_inputs["execution_start"], execution_start.get("task_file"), packet_inputs["task"]):
            blocker = controlled_loop_tick_blocker("execution_start_task_mismatch", "execution start task_file does not match supplied task file")
            step_blockers["execution_start"].append(blocker)
            blockers.append(blocker)

        snapshot_valid, snapshot_reason = validate_repo_snapshot(
            snapshot_after,
            expected_repo=repo.get("name") if isinstance(repo.get("name"), str) else None,
            expected_branch=repo.get("branch") if isinstance(repo.get("branch"), str) else None,
        )
        if not snapshot_valid:
            blocker = controlled_loop_tick_blocker("snapshot_after_invalid", f"snapshot-after evidence is invalid: {snapshot_reason}")
            step_blockers["snapshot_after"].append(blocker)
            blockers.append(blocker)

        readiness_task = readiness.get("task") if isinstance(readiness.get("task"), dict) else {}
        readiness_epoch = readiness.get("active_epoch") if isinstance(readiness.get("active_epoch"), dict) else {}
        if readiness.get("valid") is not True or readiness.get("executor_invocation_ready") is not True:
            blocker = controlled_loop_tick_blocker("readiness_not_invocable", "readiness evidence is not invocable")
            step_blockers["readiness"].append(blocker)
            blockers.append(blocker)
        if readiness_task.get("checksum") != task_checksum or readiness_task.get("id") != task_id:
            blocker = controlled_loop_tick_blocker("readiness_task_mismatch", "readiness task anchor does not match task packet")
            step_blockers["readiness"].append(blocker)
            blockers.append(blocker)
        if not _closeout_paths_match(controlled_tick_context_path(packet_inputs["readiness"], readiness_task.get("file")), packet_inputs["task"]):
            blocker = controlled_loop_tick_blocker("readiness_task_mismatch", "readiness task file does not match supplied task file")
            step_blockers["readiness"].append(blocker)
            blockers.append(blocker)
        if readiness_epoch.get("id") != epoch_id:
            blocker = controlled_loop_tick_blocker("readiness_epoch_mismatch", "readiness active epoch does not match execution start")
            step_blockers["readiness"].append(blocker)
            blockers.append(blocker)

        plan_readiness = invocation_plan.get("readiness") if isinstance(invocation_plan.get("readiness"), dict) else {}
        if invocation_plan.get("valid") is not True or invocation_plan.get("executor_invocation_planned") is not True:
            blocker = controlled_loop_tick_blocker("invocation_plan_not_invocable", "invocation plan evidence is not invocable")
            step_blockers["invocation_plan"].append(blocker)
            blockers.append(blocker)
        if plan_readiness.get("checksum") != checksum_json(readiness):
            blocker = controlled_loop_tick_blocker("invocation_plan_readiness_mismatch", "invocation plan readiness checksum does not match supplied readiness")
            step_blockers["invocation_plan"].append(blocker)
            blockers.append(blocker)
        if "file" in plan_readiness and not _closeout_paths_match(controlled_tick_context_path(packet_inputs["invocation_plan"], plan_readiness.get("file")), packet_inputs["readiness"]):
            blocker = controlled_loop_tick_blocker("invocation_plan_readiness_mismatch", "invocation plan readiness file does not match supplied readiness file")
            step_blockers["invocation_plan"].append(blocker)
            blockers.append(blocker)

        if real_invocation.get("valid") is not True or real_invocation.get("executor_started") is not True:
            blocker = controlled_loop_tick_blocker("real_invocation_invalid", "real invocation evidence must be valid and executor_started")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if not controlled_tick_non_empty_string(real_invocation.get("invocation_id")):
            blocker = controlled_loop_tick_blocker("real_invocation_identity_missing", "real invocation invocation_id is required")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("plan_checksum") != checksum_json(invocation_plan):
            blocker = controlled_loop_tick_blocker("real_invocation_plan_mismatch", "real invocation plan checksum does not match invocation plan")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("plan_target_checksum") != invocation_plan.get("target_checksum"):
            blocker = controlled_loop_tick_blocker("real_invocation_plan_mismatch", "real invocation target checksum does not match invocation plan")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if not _closeout_paths_match(controlled_tick_invocation_path(real_invocation, real_invocation.get("record_file")), packet_inputs["real_invocation"]):
            blocker = controlled_loop_tick_blocker("real_invocation_record_mismatch", "real invocation record_file does not match supplied real invocation file")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if not _closeout_paths_match(controlled_tick_invocation_path(real_invocation, real_invocation.get("plan_file")), packet_inputs["invocation_plan"]):
            blocker = controlled_loop_tick_blocker("real_invocation_plan_mismatch", "real invocation plan_file does not match supplied invocation plan file")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("result_evidence_checksum") != checksum_json(result_evidence):
            blocker = controlled_loop_tick_blocker("real_invocation_result_mismatch", "real invocation result checksum does not match supplied result")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if not _closeout_paths_match(controlled_tick_invocation_path(real_invocation, real_invocation.get("result_file")), packet_inputs["result"]):
            blocker = controlled_loop_tick_blocker("real_invocation_result_mismatch", "real invocation result_file does not match supplied result file")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)

        if result_evidence.get("task_id") != task_id:
            blocker = controlled_loop_tick_blocker("result_task_mismatch", "executor result task_id does not match task packet")
            step_blockers["result"].append(blocker)
            blockers.append(blocker)

        if closeout.get("valid") is not True:
            blocker = controlled_loop_tick_blocker("closeout_invalid", "closeout evidence must be valid")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if closeout.get("epoch_id") != epoch_id:
            blocker = controlled_loop_tick_blocker("closeout_epoch_mismatch", "closeout epoch does not match execution start")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if not controlled_tick_context_paths_match(packet_inputs["closeout"], closeout.get("task_file"), packet_inputs["task"]):
            blocker = controlled_loop_tick_blocker("closeout_task_mismatch", "closeout task_file does not match supplied task file")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if not controlled_tick_context_paths_match(packet_inputs["closeout"], closeout.get("result_file"), packet_inputs["result"]):
            blocker = controlled_loop_tick_blocker("closeout_result_mismatch", "closeout result_file does not match supplied result file")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if not controlled_tick_context_paths_match(packet_inputs["closeout"], closeout.get("snapshot_after_file"), packet_inputs["snapshot_after"]):
            blocker = controlled_loop_tick_blocker("closeout_snapshot_mismatch", "closeout snapshot_after_file does not match supplied snapshot-after file")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if closeout.get("snapshot_after_checksum") != checksum_epoch_json(snapshot_after):
            blocker = controlled_loop_tick_blocker("closeout_snapshot_mismatch", "closeout snapshot checksum does not match supplied snapshot-after evidence")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        closeout_invocation = closeout.get("real_invocation") if isinstance(closeout.get("real_invocation"), dict) else {}
        closeout_invocation_after_checksum = closeout_invocation.get("after_checksum")
        if not isinstance(closeout_invocation_after_checksum, str) or not closeout_invocation_after_checksum.strip():
            blocker = controlled_loop_tick_blocker(
                "closeout_invocation_mismatch",
                "closeout real invocation after_checksum is required for controlled tick composition",
            )
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        elif checksum_json(real_invocation) != closeout_invocation_after_checksum:
            blocker = controlled_loop_tick_blocker(
                "closeout_invocation_mismatch",
                "closeout real invocation after_checksum does not match supplied real invocation evidence",
            )
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if not controlled_tick_context_paths_match(packet_inputs["closeout"], closeout_invocation.get("path"), packet_inputs["real_invocation"]):
            blocker = controlled_loop_tick_blocker("closeout_invocation_mismatch", "closeout real invocation path does not match supplied real invocation file")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if closeout_invocation.get("invocation_id") != real_invocation.get("invocation_id"):
            blocker = controlled_loop_tick_blocker("closeout_invocation_mismatch", "closeout real invocation id does not match supplied real invocation evidence")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        closeout_validation = closeout.get("validation") if isinstance(closeout.get("validation"), dict) else {}
        if closeout_validation.get("valid") is not True:
            blocker = controlled_loop_tick_blocker("closeout_validation_mismatch", "closeout validation evidence is not valid")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        closeout_core_packet = {
            key: value
            for key, value in closeout.items()
            if key not in {"audit_record", "run_record", "real_invocation"}
        }
        epoch_closeout_checksum = checksum_json(closeout_core_packet)
        if closeout_invocation.get("epoch_closeout_checksum") != epoch_closeout_checksum:
            blocker = controlled_loop_tick_blocker("closeout_invocation_mismatch", "closeout real invocation epoch_closeout_checksum does not match closeout evidence")
            step_blockers["closeout"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("epoch_closeout_checksum") != epoch_closeout_checksum:
            blocker = controlled_loop_tick_blocker("real_invocation_closeout_mismatch", "real invocation epoch_closeout_checksum does not match closeout evidence")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("closeout_status") != closeout.get("closeout_status"):
            blocker = controlled_loop_tick_blocker("real_invocation_closeout_mismatch", "real invocation closeout_status does not match closeout evidence")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if (
            closeout.get("closeout_status") not in CONTROLLED_LOOP_TICK_TERMINAL_CLOSEOUT_STATUSES
            or real_invocation.get("closeout_status") not in CONTROLLED_LOOP_TICK_TERMINAL_CLOSEOUT_STATUSES
        ):
            blocker = controlled_loop_tick_blocker(
                "closeout_not_completed",
                "closeout and real invocation must be terminal completed or failed to emit a controlled tick",
            )
            step_blockers["closeout"].append(blocker)
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("epoch_id") != epoch_id:
            blocker = controlled_loop_tick_blocker("real_invocation_closeout_mismatch", "real invocation epoch_id does not match execution start")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("validation_packet_checksum") != checksum_json(closeout_validation):
            blocker = controlled_loop_tick_blocker("real_invocation_closeout_mismatch", "real invocation validation checksum does not match closeout validation evidence")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if real_invocation.get("snapshot_after_checksum") != checksum_epoch_json(snapshot_after):
            blocker = controlled_loop_tick_blocker("real_invocation_closeout_mismatch", "real invocation snapshot-after checksum does not match supplied snapshot-after evidence")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)
        if not _closeout_paths_match(controlled_tick_invocation_path(real_invocation, real_invocation.get("task_file")), packet_inputs["task"]):
            blocker = controlled_loop_tick_blocker("real_invocation_closeout_mismatch", "real invocation task_file does not match supplied task file")
            step_blockers["real_invocation"].append(blocker)
            blockers.append(blocker)

        embedded_git_pr_plan = closeout.get("git_pr_plan") if isinstance(closeout.get("git_pr_plan"), dict) else None
        if git_pr_plan is not None:
            if embedded_git_pr_plan is None:
                blocker = controlled_loop_tick_blocker("git_pr_plan_unanchored", "supplied git-pr plan is not embedded in closeout evidence")
                step_blockers["git_pr_plan"].append(blocker)
                blockers.append(blocker)
            elif checksum_json(git_pr_plan) != checksum_json(embedded_git_pr_plan):
                blocker = controlled_loop_tick_blocker("git_pr_plan_mismatch", "supplied git-pr plan does not match closeout embedded git-pr plan")
                step_blockers["git_pr_plan"].append(blocker)
                blockers.append(blocker)

    valid = not blockers
    tick_id = f"controlled-loop-tick-{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}-{secrets.token_hex(4)}"
    loop_tick = packets.get("loop_tick") if isinstance(packets.get("loop_tick"), dict) else {}
    task_packet = packets.get("task") if isinstance(packets.get("task"), dict) else {}
    execution_start = packets.get("execution_start") if isinstance(packets.get("execution_start"), dict) else {}
    real_invocation = packets.get("real_invocation") if isinstance(packets.get("real_invocation"), dict) else {}
    closeout = packets.get("closeout") if isinstance(packets.get("closeout"), dict) else {}
    task = task_packet.get("task") if isinstance(task_packet.get("task"), dict) else {}
    next_decision = closeout.get("next_decision") if isinstance(closeout.get("next_decision"), dict) else {}
    checksums = {
        name: checksum_json(packet)
        for name, packet in packets.items()
        if isinstance(packet, dict)
    }
    files = {name: str(path) for name, path in packet_inputs.items()}
    if optional_git_pr_plan is not None:
        files["git_pr_plan"] = str(optional_git_pr_plan)
    steps = [
        controlled_tick_step(name, path, packets.get(name), "accepted" if not step_blockers.get(name) else "blocked", step_blockers.get(name, []))
        for name, path in packet_inputs.items()
    ]
    if optional_git_pr_plan is not None:
        steps.append(
            controlled_tick_step(
                "git_pr_plan",
                optional_git_pr_plan,
                packets.get("git_pr_plan"),
                "accepted" if not step_blockers.get("git_pr_plan") else "blocked",
                step_blockers.get("git_pr_plan", []),
            )
        )
    recommended_next_action = "controlled_tick_complete" if valid else "inspect_controlled_tick_blockers"
    reason = "controlled loop tick evidence is internally consistent" if valid else "controlled loop tick evidence is incomplete or mismatched"
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_TICK_SCHEMA_VERSION,
        "packet": "controlled_loop_tick",
        "generated_at": utc_now(),
        "tick_id": tick_id,
        "source_tick_id": loop_tick.get("tick_id"),
        "valid": valid,
        "controlled_tick_status": "completed" if valid else "blocked",
        "reason": reason,
        "executor_started": real_invocation.get("executor_started") is True,
        "side_effects": [],
        "recommended_next_action": recommended_next_action,
        "operator_confirmation_required": not valid,
        "task": {
            "id": task.get("id"),
            "checksum": checksums.get("task"),
            "source": task.get("source"),
        },
        "epoch": {
            "id": execution_start.get("epoch_id"),
            "closeout_status": closeout.get("closeout_status"),
            "epoch_status": closeout.get("epoch_status"),
        },
        "real_invocation": {
            "invocation_id": real_invocation.get("invocation_id"),
            "side_effect_mode": real_invocation.get("side_effect_mode"),
            "closeout_status": real_invocation.get("closeout_status"),
        },
        "next_decision": next_decision,
        "files": files,
        "checksums": checksums,
        "steps": steps,
        "blockers": blockers,
        "limitations": [
            "composes_existing_local_evidence_only",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_rewrite_invocation_or_closeout_records",
            "does_not_execute_git_commands",
            "does_not_call_github",
            "does_not_create_branch_commit_push_or_pr",
            "does_not_merge_release_or_publish_packages",
            "does_not_assign_roles_or_claim_distributed_locks",
        ],
    }
    if valid:
        payload["side_effects"].append("controlled_loop_tick_audit_appended")
        try:
            audit_record = controlled_loop_tick_audit_record(payload)
            audit_blockers = validate_controlled_loop_tick_audit_record(audit_record, 0)
            if audit_blockers:
                raise ValueError(f"controlled_loop_tick audit record is invalid: {audit_blockers[0]['code']}")
            payload["audit_record"] = append_audit_record(args.root, audit_record)
        except Exception as exc:
            payload["valid"] = False
            payload["controlled_tick_status"] = "blocked"
            payload["reason"] = "controlled loop tick audit record could not be written"
            payload["recommended_next_action"] = "recover_controlled_tick_audit"
            payload["operator_confirmation_required"] = True
            payload["side_effects"] = []
            payload["blockers"] = [
                {
                    "code": "controlled_loop_tick_audit_append_failed",
                    "message": "controlled loop tick audit record could not be written",
                    "error": str(exc),
                }
            ]
            emit(payload)
            return 2
    emit(payload)
    return 0 if payload["valid"] else 1


CONTROLLED_LOOP_RUN_SUMMARY_SCHEMA_VERSION = "controlled-loop-run-summary.v1"


def controlled_loop_run_summary_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_run_summary_packet(
    path: Path,
    *,
    code: str,
    label: str,
) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [
            controlled_loop_run_summary_blocker(
                code,
                f"{label} could not be read as JSON",
                path=str(path),
                error=str(exc),
            )
        ]
    if not isinstance(packet, dict):
        return None, [controlled_loop_run_summary_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_loop_run_summary_type_blockers(
    packet: dict[str, Any],
    *,
    label: str,
    expected_packet: str,
    expected_schema: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if packet.get("schema_version") != expected_schema:
        blockers.append(
            controlled_loop_run_summary_blocker(
                "controlled_run_packet_mismatch",
                f"{label} schema_version is invalid",
                expected=expected_schema,
                actual=packet.get("schema_version"),
            )
        )
    if packet.get("packet") != expected_packet:
        blockers.append(
            controlled_loop_run_summary_blocker(
                "controlled_run_packet_mismatch",
                f"{label} packet is invalid",
                expected=expected_packet,
                actual=packet.get("packet"),
            )
        )
    return blockers


def controlled_loop_run_summary_step(
    name: str,
    path: Path,
    packet: Any,
    blockers: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "name": name,
        "status": "accepted" if not blockers else "blocked",
        "file": str(path),
        "checksum": checksum_json(packet) if isinstance(packet, dict) else None,
        "blocker_codes": [blocker["code"] for blocker in blockers],
    }


def controlled_loop_run_summary_add_blocker(
    blockers: list[dict[str, Any]],
    step_blockers: dict[str, list[dict[str, Any]]],
    step: str,
    code: str,
    message: str,
    **extra: Any,
) -> None:
    blocker = controlled_loop_run_summary_blocker(code, message, **extra)
    step_blockers[step].append(blocker)
    blockers.append(blocker)


def controlled_loop_run_summary_file_matches(context_file: Path, value: Any, expected_path: Path) -> bool:
    return _closeout_paths_match(controlled_tick_context_path(context_file, value), expected_path)


def controlled_loop_run_summary_non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def controlled_loop_run_summary_command(args: argparse.Namespace) -> int:
    packet_inputs = {
        "loop_run_plan": Path(args.loop_run_plan_file),
        "controlled_loop_start": Path(args.controlled_loop_start_file),
        "controlled_invocation_plan": Path(args.controlled_invocation_plan_file),
        "controlled_real_invocation": Path(args.controlled_real_invocation_file),
        "controlled_closeout": Path(args.controlled_closeout_file),
        "controlled_loop_tick": Path(args.controlled_loop_tick_file),
    }
    read_codes = {
        "loop_run_plan": "loop_run_plan_evidence_missing",
        "controlled_loop_start": "controlled_loop_start_evidence_missing",
        "controlled_invocation_plan": "controlled_invocation_plan_evidence_missing",
        "controlled_real_invocation": "controlled_real_invocation_evidence_missing",
        "controlled_closeout": "controlled_closeout_evidence_missing",
        "controlled_loop_tick": "controlled_loop_tick_evidence_missing",
    }
    packets: dict[str, Any] = {}
    blockers: list[dict[str, Any]] = []
    step_blockers: dict[str, list[dict[str, Any]]] = {}
    for name, path in packet_inputs.items():
        packet, packet_blockers = read_controlled_loop_run_summary_packet(
            path,
            code=read_codes[name],
            label=name.replace("_", " "),
        )
        packets[name] = packet
        step_blockers[name] = list(packet_blockers)
        blockers.extend(packet_blockers)

    if not blockers:
        expected_types = {
            "loop_run_plan": ("loop_run_plan", LOOP_RUN_PLAN_SCHEMA_VERSION),
            "controlled_loop_start": ("controlled_loop_start", CONTROLLED_LOOP_START_SCHEMA_VERSION),
            "controlled_invocation_plan": ("controlled_loop_invocation_plan", CONTROLLED_LOOP_INVOCATION_PLAN_SCHEMA_VERSION),
            "controlled_real_invocation": ("controlled_loop_real_invocation", CONTROLLED_LOOP_REAL_INVOCATION_SCHEMA_VERSION),
            "controlled_closeout": ("controlled_loop_closeout", CONTROLLED_LOOP_CLOSEOUT_SCHEMA_VERSION),
            "controlled_loop_tick": ("controlled_loop_tick", CONTROLLED_LOOP_TICK_SCHEMA_VERSION),
        }
        for name, (expected_packet, expected_schema) in expected_types.items():
            packet_blockers = controlled_loop_run_summary_type_blockers(
                packets[name],
                label=name.replace("_", " "),
                expected_packet=expected_packet,
                expected_schema=expected_schema,
            )
            step_blockers[name].extend(packet_blockers)
            blockers.extend(packet_blockers)

    if not blockers:
        loop_run_plan = packets["loop_run_plan"]
        controlled_start = packets["controlled_loop_start"]
        controlled_plan = packets["controlled_invocation_plan"]
        controlled_real = packets["controlled_real_invocation"]
        controlled_closeout = packets["controlled_closeout"]
        controlled_tick = packets["controlled_loop_tick"]

        status_specs = {
            "controlled_loop_start": ("controlled_start_status", "plan_executor_invocation"),
            "controlled_invocation_plan": ("controlled_invocation_plan_status", "invoke_real_executor"),
            "controlled_real_invocation": ("controlled_real_invocation_status", "closeout_executor_result"),
            "controlled_closeout": ("controlled_closeout_status", "controlled_loop_tick"),
            "controlled_loop_tick": ("controlled_tick_status", "controlled_tick_complete"),
        }
        expected_side_effects = {
            "controlled_loop_start": [],
            "controlled_invocation_plan": [],
            "controlled_real_invocation": [],
            "controlled_closeout": [],
            "controlled_loop_tick": ["controlled_loop_tick_audit_appended"],
        }
        if loop_run_plan.get("recommended_next_action") != "request_operator_approval":
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "loop_run_plan",
                "loop_run_plan_not_ready",
                "loop run plan must be ready for operator approval",
                actual=loop_run_plan.get("recommended_next_action"),
            )
        for name, (status_field, expected_action) in status_specs.items():
            packet = packets[name]
            if packet.get("valid") is not True or packet.get(status_field) != "completed":
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    name,
                    f"{name}_not_completed",
                    f"{name.replace('_', ' ')} must be valid and completed",
                    valid=packet.get("valid"),
                    status=packet.get(status_field),
                )
            if packet.get("recommended_next_action") != expected_action:
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    name,
                    f"{name}_unexpected_next_action",
                    f"{name.replace('_', ' ')} recommended next action is invalid",
                    expected=expected_action,
                    actual=packet.get("recommended_next_action"),
                )
            if packet.get("blockers") != []:
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    name,
                    f"{name}_unexpected_blockers",
                    f"{name.replace('_', ' ')} must not carry blockers when completed",
                    actual=packet.get("blockers"),
                )
            if packet.get("operator_confirmation_required") is not False:
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    name,
                    f"{name}_unexpected_operator_confirmation",
                    f"{name.replace('_', ' ')} must not require operator confirmation when completed",
                    actual=packet.get("operator_confirmation_required"),
                )
            if packet.get("side_effects") != expected_side_effects[name]:
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    name,
                    f"{name}_unexpected_side_effects",
                    f"{name.replace('_', ' ')} side effects are invalid for completed evidence",
                    expected=expected_side_effects[name],
                    actual=packet.get("side_effects"),
                )

        expected_links = [
            (
                "controlled_loop_start",
                controlled_start,
                "loop_run_plan_checksum",
                "loop_run_plan",
                checksum_json(loop_run_plan),
                "loop_run_plan",
                packet_inputs["loop_run_plan"],
            ),
            (
                "controlled_invocation_plan",
                controlled_plan,
                "controlled_loop_start_checksum",
                "controlled_loop_start",
                checksum_json(controlled_start),
                "controlled_loop_start",
                packet_inputs["controlled_loop_start"],
            ),
            (
                "controlled_real_invocation",
                controlled_real,
                "controlled_invocation_plan_checksum",
                "controlled_invocation_plan",
                checksum_json(controlled_plan),
                "controlled_invocation_plan",
                packet_inputs["controlled_invocation_plan"],
            ),
            (
                "controlled_closeout",
                controlled_closeout,
                "controlled_real_invocation_checksum",
                "controlled_real_invocation",
                checksum_json(controlled_real),
                "controlled_real_invocation",
                packet_inputs["controlled_real_invocation"],
            ),
        ]
        for step, packet, checksum_field, code_prefix, expected_checksum, file_key, expected_path in expected_links:
            if packet.get(checksum_field) != expected_checksum:
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    file_key,
                    f"{code_prefix}_checksum_mismatch",
                    f"{step.replace('_', ' ')} {checksum_field} does not match supplied evidence",
                    expected=expected_checksum,
                    actual=packet.get(checksum_field),
                )
            files = packet.get("files") if isinstance(packet.get("files"), dict) else {}
            if file_key not in files:
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    step,
                    f"{code_prefix}_file_mismatch",
                    f"{step.replace('_', ' ')} {file_key} file anchor is missing",
                    expected=str(expected_path),
                    actual=packet.get("files"),
                )
            elif not controlled_loop_run_summary_file_matches(packet_inputs[step], files.get(file_key), expected_path):
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    step,
                    f"{code_prefix}_file_mismatch",
                    f"{step.replace('_', ' ')} {file_key} file does not match supplied evidence path",
                    expected=str(expected_path),
                    actual=files.get(file_key),
                )

        controlled_tick_checksums = controlled_tick.get("checksums") if isinstance(controlled_tick.get("checksums"), dict) else {}
        controlled_tick_expected_checksums = {
            "loop_tick": loop_run_plan.get("loop_tick_checksum"),
            "task": loop_run_plan.get("executor_task_checksum"),
            "execution_start": controlled_start.get("execution_start_checksum"),
            "readiness": controlled_plan.get("readiness_checksum"),
            "invocation_plan": controlled_plan.get("invocation_plan_checksum"),
            "result": controlled_real.get("result_evidence_checksum"),
        }
        for checksum_name, expected_checksum in controlled_tick_expected_checksums.items():
            if not controlled_loop_run_summary_non_empty_string(expected_checksum):
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    "controlled_loop_tick",
                    f"controlled_tick_{checksum_name}_checksum_mismatch",
                    f"controlled loop tick expected {checksum_name} checksum is missing from upstream evidence",
                    actual=expected_checksum,
                )
            elif controlled_tick_checksums.get(checksum_name) != expected_checksum:
                controlled_loop_run_summary_add_blocker(
                    blockers,
                    step_blockers,
                    "controlled_loop_tick",
                    f"controlled_tick_{checksum_name}_checksum_mismatch",
                    f"controlled loop tick {checksum_name} checksum does not match upstream evidence",
                    expected=expected_checksum,
                    actual=controlled_tick_checksums.get(checksum_name),
                )
        controlled_tick_task = controlled_tick.get("task") if isinstance(controlled_tick.get("task"), dict) else {}
        if controlled_tick_task.get("checksum") != loop_run_plan.get("executor_task_checksum"):
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_tick_task_checksum_mismatch",
                "controlled loop tick task checksum does not match loop-run-plan executor task checksum",
                expected=loop_run_plan.get("executor_task_checksum"),
                actual=controlled_tick_task.get("checksum"),
            )
        if controlled_tick_checksums.get("closeout") != controlled_closeout.get("closeout_checksum"):
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_tick_closeout_checksum_mismatch",
                "controlled loop tick closeout checksum does not match controlled closeout evidence",
                expected=controlled_closeout.get("closeout_checksum"),
                actual=controlled_tick_checksums.get("closeout"),
            )
        if controlled_tick_checksums.get("real_invocation") != controlled_closeout.get("real_invocation_after_checksum"):
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_tick_real_invocation_checksum_mismatch",
                "controlled loop tick real invocation checksum does not match controlled closeout evidence",
                expected=controlled_closeout.get("real_invocation_after_checksum"),
                actual=controlled_tick_checksums.get("real_invocation"),
            )
        loop_tick = loop_run_plan.get("loop_tick") if isinstance(loop_run_plan.get("loop_tick"), dict) else {}
        if controlled_tick.get("source_tick_id") != loop_tick.get("tick_id"):
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_tick_source_mismatch",
                "controlled loop tick source_tick_id does not match loop-run-plan tick",
                expected=loop_tick.get("tick_id"),
                actual=controlled_tick.get("source_tick_id"),
            )
        task_ids = {
            "controlled_start": controlled_start.get("task_id"),
            "controlled_plan": controlled_plan.get("task_id"),
            "controlled_real": controlled_real.get("task_id"),
            "controlled_closeout": controlled_closeout.get("task_id"),
            "controlled_tick": (controlled_tick.get("task") if isinstance(controlled_tick.get("task"), dict) else {}).get("id"),
        }
        missing_task_ids = {
            name: task_id
            for name, task_id in task_ids.items()
            if not controlled_loop_run_summary_non_empty_string(task_id)
        }
        if missing_task_ids:
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_run_task_mismatch",
                "controlled run task ids are required",
                task_ids=task_ids,
            )
        elif len(set(task_ids.values())) > 1:
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_run_task_mismatch",
                "controlled run task ids do not match",
                task_ids=task_ids,
            )
        epoch_ids = {
            "controlled_start": controlled_start.get("epoch_id"),
            "controlled_plan": controlled_plan.get("epoch_id"),
            "controlled_real": controlled_real.get("epoch_id"),
            "controlled_closeout": controlled_closeout.get("epoch_id"),
            "controlled_tick": (controlled_tick.get("epoch") if isinstance(controlled_tick.get("epoch"), dict) else {}).get("id"),
        }
        missing_epoch_ids = {
            name: epoch_id
            for name, epoch_id in epoch_ids.items()
            if not controlled_loop_run_summary_non_empty_string(epoch_id)
        }
        if missing_epoch_ids:
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_run_epoch_mismatch",
                "controlled run epoch ids are required",
                epoch_ids=epoch_ids,
            )
        elif len(set(epoch_ids.values())) > 1:
            controlled_loop_run_summary_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_run_epoch_mismatch",
                "controlled run epoch ids do not match",
                epoch_ids=epoch_ids,
            )

    valid = not blockers
    controlled_tick = packets.get("controlled_loop_tick") if isinstance(packets.get("controlled_loop_tick"), dict) else {}
    controlled_closeout = packets.get("controlled_closeout") if isinstance(packets.get("controlled_closeout"), dict) else {}
    controlled_start = packets.get("controlled_loop_start") if isinstance(packets.get("controlled_loop_start"), dict) else {}
    task = controlled_tick.get("task") if isinstance(controlled_tick.get("task"), dict) else {}
    epoch = controlled_tick.get("epoch") if isinstance(controlled_tick.get("epoch"), dict) else {}
    real_invocation = controlled_tick.get("real_invocation") if isinstance(controlled_tick.get("real_invocation"), dict) else {}
    checksums = {name: checksum_json(packet) for name, packet in packets.items() if isinstance(packet, dict)}
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_RUN_SUMMARY_SCHEMA_VERSION,
        "packet": "controlled_loop_run_summary",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "controlled_run_status": "completed" if valid else "blocked",
        "reason": "controlled loop run evidence chain matches" if valid else "controlled loop run evidence is incomplete or mismatched",
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": False if valid else True,
        "side_effects": [],
        "recommended_next_action": "review_controlled_loop_run" if valid else "inspect_controlled_loop_run_blockers",
        "source_tick_id": controlled_tick.get("source_tick_id"),
        "task": {
            "id": task.get("id") or controlled_start.get("task_id"),
            "checksum": task.get("checksum"),
        },
        "epoch": {
            "id": epoch.get("id") or controlled_start.get("epoch_id"),
            "closeout_status": epoch.get("closeout_status") or controlled_closeout.get("closeout_status"),
            "epoch_status": epoch.get("epoch_status") or controlled_closeout.get("epoch_status"),
        },
        "real_invocation": real_invocation,
        "summarized_controlled_tick": {
            "executor_started": controlled_tick.get("executor_started") is True,
            "side_effects": controlled_tick.get("side_effects") if isinstance(controlled_tick.get("side_effects"), list) else [],
        },
        "next_decision": controlled_tick.get("next_decision") if isinstance(controlled_tick.get("next_decision"), dict) else {},
        "files": {name: str(path) for name, path in packet_inputs.items()},
        "checksums": checksums,
        "steps": [
            controlled_loop_run_summary_step(name, path, packets.get(name), step_blockers.get(name, []))
            for name, path in packet_inputs.items()
        ],
        "blockers": blockers,
        "limitations": [
            "composes_existing_controlled_loop_packets_only",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_continue_loop",
            "does_not_close_epoch",
            "does_not_rewrite_invocation_or_closeout_records",
            "does_not_append_audit",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_OUTCOME_PLAN_SCHEMA_VERSION = "controlled-loop-outcome-plan.v1"


def controlled_loop_outcome_plan_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_outcome_plan_packet(
    path: Path,
    *,
    code: str,
    label: str,
) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [
            controlled_loop_outcome_plan_blocker(
                code,
                f"{label} could not be read as JSON",
                path=str(path),
                error=str(exc),
            )
        ]
    if not isinstance(packet, dict):
        return None, [controlled_loop_outcome_plan_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_loop_outcome_plan_type_blockers(
    packet: dict[str, Any],
    *,
    label: str,
    expected_packet: str,
    expected_schema: str,
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if packet.get("schema_version") != expected_schema:
        blockers.append(
            controlled_loop_outcome_plan_blocker(
                "controlled_loop_outcome_packet_mismatch",
                f"{label} schema_version is invalid",
                expected=expected_schema,
                actual=packet.get("schema_version"),
            )
        )
    if packet.get("packet") != expected_packet:
        blockers.append(
            controlled_loop_outcome_plan_blocker(
                "controlled_loop_outcome_packet_mismatch",
                f"{label} packet is invalid",
                expected=expected_packet,
                actual=packet.get("packet"),
            )
        )
    return blockers


def controlled_loop_outcome_plan_step(
    name: str,
    path: Path,
    packet: Any,
    blockers: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "name": name,
        "status": "accepted" if not blockers else "blocked",
        "file": str(path),
        "checksum": checksum_json(packet) if isinstance(packet, dict) else None,
        "blocker_codes": [blocker["code"] for blocker in blockers],
    }


def controlled_loop_outcome_plan_add_blocker(
    blockers: list[dict[str, Any]],
    step_blockers: dict[str, list[dict[str, Any]]],
    step: str,
    code: str,
    message: str,
    **extra: Any,
) -> None:
    blocker = controlled_loop_outcome_plan_blocker(code, message, **extra)
    step_blockers[step].append(blocker)
    blockers.append(blocker)


def controlled_loop_outcome_plan_add_existing_blocker(
    blockers: list[dict[str, Any]],
    step_blockers: dict[str, list[dict[str, Any]]],
    step: str,
    blocker: dict[str, Any],
) -> None:
    step_blockers[step].append(blocker)
    blockers.append(blocker)


def controlled_loop_outcome_plan_file_matches(context_file: Path, value: Any, expected_path: Path) -> bool:
    return _closeout_paths_match(controlled_tick_context_path(context_file, value), expected_path)


CONTROLLED_LOOP_OUTCOME_SOURCE_ACTIONS = {
    "generate_git_pr_plan": {
        "run_git_pr_plan",
        "review_git_pr_plan",
        "provide_template_or_sections",
        "update_pr_body",
        "address_blockers",
        "provide_runtime_root",
        "stop_active_loop",
    },
    "continue": {"wait_for_next_executor_result"},
    "handoff": {"prepare_handoff"},
    "stop": {"stop_active_loop", "inspect_epoch_state", "review_stop_decision"},
    "validate_more_evidence": {"fix_executor_evidence"},
}


def controlled_loop_outcome_recommendation(
    blockers: list[dict[str, Any]],
    *,
    source_decision: dict[str, Any],
    git_pr_plan: dict[str, Any] | None,
) -> tuple[str, bool, str]:
    if blockers:
        blocker_codes = {blocker.get("code") for blocker in blockers}
        if any(
            code in blocker_codes
            for code in {
                "controlled_run_summary_evidence_missing",
                "controlled_run_summary_not_completed",
                "controlled_run_summary_checksum_mismatch",
                "controlled_loop_tick_checksum_mismatch",
                "controlled_closeout_checksum_mismatch",
                "controlled_loop_outcome_packet_mismatch",
                "controlled_closeout_file_mismatch",
                "controlled_loop_tick_file_mismatch",
                "controlled_closeout_embedded_closeout_checksum_mismatch",
                "controlled_loop_tick_closeout_checksum_mismatch",
                "controlled_loop_tick_real_invocation_checksum_mismatch",
            }
        ):
            return "refresh_controlled_loop_run_summary", True, "controlled run summary or terminal evidence is stale"
        if any(isinstance(code, str) and code.startswith("git_pr_plan_") for code in blocker_codes):
            return "inspect_git_pr_plan_blockers", True, "controlled run Git/PR plan is not ready for approval"
        return "inspect_controlled_loop_outcome_blockers", True, "controlled loop outcome evidence is blocked"

    decision = source_decision.get("decision")
    if decision == "generate_git_pr_plan":
        if git_pr_plan is None:
            return "run_git_pr_plan", False, "controlled run completed and needs a dry-run Git/PR plan"
        if not validate_git_pr_plan_dry_run_packet(git_pr_plan):
            return "request_git_pr_materialization_approval", True, "controlled run has a ready dry-run Git/PR plan"
        return "inspect_git_pr_plan_blockers", True, "controlled run Git/PR plan is not ready for approval"
    if decision == "continue":
        return "plan_next_controlled_executor_step", True, "controlled run completed one task and the epoch remains active"
    if decision == "handoff":
        return "inspect_executor_failure", True, "controlled run ended with executor failure evidence"
    if decision == "stop":
        return source_decision.get("recommended_next_action", "review_stop_decision"), True, "controlled run ended with a stop decision"
    if decision == "validate_more_evidence":
        return source_decision.get("recommended_next_action", "fix_executor_evidence"), True, "controlled run needs more executor evidence"
    return "inspect_controlled_loop_outcome_blockers", True, "controlled run outcome decision is not supported"


def controlled_loop_outcome_plan_command(args: argparse.Namespace) -> int:
    packet_inputs = {
        "controlled_run_summary": Path(args.controlled_run_summary_file),
        "controlled_closeout": Path(args.controlled_closeout_file),
        "controlled_loop_tick": Path(args.controlled_loop_tick_file),
    }
    read_codes = {
        "controlled_run_summary": "controlled_run_summary_evidence_missing",
        "controlled_closeout": "controlled_closeout_evidence_missing",
        "controlled_loop_tick": "controlled_loop_tick_evidence_missing",
    }
    packets: dict[str, Any] = {}
    blockers: list[dict[str, Any]] = []
    step_blockers: dict[str, list[dict[str, Any]]] = {}
    for name, path in packet_inputs.items():
        packet, packet_blockers = read_controlled_loop_outcome_plan_packet(
            path,
            code=read_codes[name],
            label=name.replace("_", " "),
        )
        packets[name] = packet
        step_blockers[name] = list(packet_blockers)
        blockers.extend(packet_blockers)

    if not blockers:
        expected_types = {
            "controlled_run_summary": ("controlled_loop_run_summary", CONTROLLED_LOOP_RUN_SUMMARY_SCHEMA_VERSION),
            "controlled_closeout": ("controlled_loop_closeout", CONTROLLED_LOOP_CLOSEOUT_SCHEMA_VERSION),
            "controlled_loop_tick": ("controlled_loop_tick", CONTROLLED_LOOP_TICK_SCHEMA_VERSION),
        }
        for name, (expected_packet, expected_schema) in expected_types.items():
            packet_blockers = controlled_loop_outcome_plan_type_blockers(
                packets[name],
                label=name.replace("_", " "),
                expected_packet=expected_packet,
                expected_schema=expected_schema,
            )
            step_blockers[name].extend(packet_blockers)
            blockers.extend(packet_blockers)

    if not blockers:
        summary = packets["controlled_run_summary"]
        controlled_closeout = packets["controlled_closeout"]
        controlled_tick = packets["controlled_loop_tick"]
        closeout = controlled_closeout.get("closeout") if isinstance(controlled_closeout.get("closeout"), dict) else {}

        if (
            summary.get("valid") is not True
            or summary.get("controlled_run_status") != "completed"
            or summary.get("recommended_next_action") != "review_controlled_loop_run"
            or summary.get("side_effects") != []
        ):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_run_summary",
                "controlled_run_summary_not_completed",
                "controlled run summary must be valid, completed, and ready for review",
                valid=summary.get("valid"),
                status=summary.get("controlled_run_status"),
                recommended_next_action=summary.get("recommended_next_action"),
            )
        if (
            controlled_closeout.get("valid") is not True
            or controlled_closeout.get("controlled_closeout_status") != "completed"
            or controlled_closeout.get("recommended_next_action") != "controlled_loop_tick"
            or controlled_closeout.get("side_effects") != []
        ):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_closeout",
                "controlled_closeout_not_completed",
                "controlled closeout must be valid and completed",
                valid=controlled_closeout.get("valid"),
                status=controlled_closeout.get("controlled_closeout_status"),
                recommended_next_action=controlled_closeout.get("recommended_next_action"),
            )
        if (
            controlled_tick.get("valid") is not True
            or controlled_tick.get("controlled_tick_status") != "completed"
            or controlled_tick.get("recommended_next_action") != "controlled_tick_complete"
        ):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_tick_not_completed",
                "controlled loop tick must be valid and completed",
                valid=controlled_tick.get("valid"),
                status=controlled_tick.get("controlled_tick_status"),
                recommended_next_action=controlled_tick.get("recommended_next_action"),
            )

        summary_checksums = summary.get("checksums") if isinstance(summary.get("checksums"), dict) else {}
        if summary_checksums.get("controlled_closeout") != checksum_json(controlled_closeout):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_closeout",
                "controlled_closeout_checksum_mismatch",
                "controlled closeout checksum does not match controlled run summary",
                expected=summary_checksums.get("controlled_closeout"),
                actual=checksum_json(controlled_closeout),
            )
        if summary_checksums.get("controlled_loop_tick") != checksum_json(controlled_tick):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_tick_checksum_mismatch",
                "controlled loop tick checksum does not match controlled run summary",
                expected=summary_checksums.get("controlled_loop_tick"),
                actual=checksum_json(controlled_tick),
            )
        summary_files = summary.get("files") if isinstance(summary.get("files"), dict) else {}
        for key, path in {
            "controlled_closeout": packet_inputs["controlled_closeout"],
            "controlled_loop_tick": packet_inputs["controlled_loop_tick"],
        }.items():
            if key not in summary_files:
                controlled_loop_outcome_plan_add_blocker(
                    blockers,
                    step_blockers,
                    "controlled_run_summary",
                    f"{key}_file_mismatch",
                    f"controlled run summary files.{key} anchor is missing",
                    expected=str(path),
                    actual=summary.get("files"),
                )
            elif not controlled_loop_outcome_plan_file_matches(packet_inputs["controlled_run_summary"], summary_files.get(key), path):
                controlled_loop_outcome_plan_add_blocker(
                    blockers,
                    step_blockers,
                    "controlled_run_summary",
                    f"{key}_file_mismatch",
                    f"controlled run summary files.{key} does not match supplied evidence path",
                    expected=str(path),
                    actual=summary_files.get(key),
                )

        tick_checksums = controlled_tick.get("checksums") if isinstance(controlled_tick.get("checksums"), dict) else {}
        closeout_checksum = checksum_json(closeout) if closeout else None
        if closeout_checksum is None:
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_closeout",
                "controlled_closeout_embedded_closeout_checksum_mismatch",
                "controlled closeout must embed the accepted closeout evidence",
                actual=controlled_closeout.get("closeout"),
            )
        elif controlled_closeout.get("closeout_checksum") != closeout_checksum:
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_closeout",
                "controlled_closeout_embedded_closeout_checksum_mismatch",
                "controlled closeout checksum does not match embedded closeout evidence",
                expected=controlled_closeout.get("closeout_checksum"),
                actual=closeout_checksum,
            )
        if tick_checksums.get("closeout") != closeout_checksum:
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_tick_closeout_checksum_mismatch",
                "controlled loop tick closeout checksum does not match controlled closeout",
                expected=closeout_checksum,
                actual=tick_checksums.get("closeout"),
            )
        if tick_checksums.get("real_invocation") != controlled_closeout.get("real_invocation_after_checksum"):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_tick_real_invocation_checksum_mismatch",
                "controlled loop tick real invocation checksum does not match controlled closeout",
                expected=controlled_closeout.get("real_invocation_after_checksum"),
                actual=tick_checksums.get("real_invocation"),
            )
        if summary.get("next_decision") != controlled_tick.get("next_decision"):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_run_summary",
                "controlled_run_summary_decision_mismatch",
                "controlled run summary next_decision does not match controlled loop tick",
                expected=controlled_tick.get("next_decision"),
                actual=summary.get("next_decision"),
            )
        closeout_next_decision = closeout.get("next_decision") if isinstance(closeout.get("next_decision"), dict) else {}
        if closeout_next_decision != controlled_tick.get("next_decision"):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_outcome_closeout_decision_mismatch",
                "controlled loop tick next_decision does not match embedded closeout evidence",
                expected=closeout_next_decision,
                actual=controlled_tick.get("next_decision"),
            )

        tick_task = controlled_tick.get("task") if isinstance(controlled_tick.get("task"), dict) else {}
        tick_epoch = controlled_tick.get("epoch") if isinstance(controlled_tick.get("epoch"), dict) else {}
        if controlled_closeout.get("task_id") != tick_task.get("id"):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_outcome_task_mismatch",
                "controlled loop tick task does not match controlled closeout",
                expected=controlled_closeout.get("task_id"),
                actual=tick_task.get("id"),
            )
        if controlled_closeout.get("epoch_id") != tick_epoch.get("id"):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_outcome_epoch_mismatch",
                "controlled loop tick epoch does not match controlled closeout",
                expected=controlled_closeout.get("epoch_id"),
                actual=tick_epoch.get("id"),
            )
        if controlled_closeout.get("closeout_status") != tick_epoch.get("closeout_status"):
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_outcome_closeout_status_mismatch",
                "controlled loop tick closeout status does not match controlled closeout",
                expected=controlled_closeout.get("closeout_status"),
                actual=tick_epoch.get("closeout_status"),
            )

        source_decision = controlled_tick.get("next_decision") if isinstance(controlled_tick.get("next_decision"), dict) else {}
        source_decision_name = source_decision.get("decision")
        source_recommended_action = source_decision.get("recommended_next_action")
        if source_decision_name not in CONTROLLED_LOOP_OUTCOME_SOURCE_ACTIONS:
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_outcome_decision_unsupported",
                "controlled loop outcome decision is unsupported",
                actual=source_decision,
            )
        elif source_recommended_action not in CONTROLLED_LOOP_OUTCOME_SOURCE_ACTIONS[source_decision_name]:
            controlled_loop_outcome_plan_add_blocker(
                blockers,
                step_blockers,
                "controlled_loop_tick",
                "controlled_loop_outcome_action_unsupported",
                "controlled loop outcome recommended action is unsupported",
                decision=source_decision_name,
                actual=source_recommended_action,
                allowed=sorted(CONTROLLED_LOOP_OUTCOME_SOURCE_ACTIONS[source_decision_name]),
            )
        if source_decision_name == "generate_git_pr_plan":
            git_pr_plan = closeout.get("git_pr_plan") if isinstance(closeout.get("git_pr_plan"), dict) else None
            if git_pr_plan is not None:
                git_pr_plan_checksum = checksum_json(git_pr_plan)
                for git_pr_blocker in validate_git_pr_plan_dry_run_packet(git_pr_plan):
                    controlled_loop_outcome_plan_add_existing_blocker(
                        blockers,
                        step_blockers,
                        "controlled_closeout",
                        dict(git_pr_blocker),
                    )
                tick_files = controlled_tick.get("files") if isinstance(controlled_tick.get("files"), dict) else {}
                git_pr_plan_file = controlled_tick_context_path(
                    packet_inputs["controlled_loop_tick"],
                    tick_files.get("git_pr_plan"),
                )
                if tick_checksums.get("git_pr_plan") != git_pr_plan_checksum:
                    controlled_loop_outcome_plan_add_blocker(
                        blockers,
                        step_blockers,
                        "controlled_loop_tick",
                        "git_pr_plan_checksum_mismatch",
                        "controlled loop tick git-pr plan checksum does not match embedded closeout plan",
                        expected=git_pr_plan_checksum,
                        actual=tick_checksums.get("git_pr_plan"),
                    )
                if not isinstance(git_pr_plan_file, Path):
                    controlled_loop_outcome_plan_add_blocker(
                        blockers,
                        step_blockers,
                        "controlled_loop_tick",
                        "git_pr_plan_unanchored",
                        "controlled loop tick must anchor the embedded git-pr plan file before approval",
                        actual=tick_files.get("git_pr_plan"),
                    )
                else:
                    git_pr_plan_packet, git_pr_plan_read_blockers = read_controlled_loop_outcome_plan_packet(
                        git_pr_plan_file,
                        code="git_pr_plan_evidence_missing",
                        label="git pr plan",
                    )
                    for read_blocker in git_pr_plan_read_blockers:
                        controlled_loop_outcome_plan_add_existing_blocker(
                            blockers,
                            step_blockers,
                            "controlled_loop_tick",
                            read_blocker,
                        )
                    if isinstance(git_pr_plan_packet, dict):
                        if checksum_json(git_pr_plan_packet) != git_pr_plan_checksum:
                            controlled_loop_outcome_plan_add_blocker(
                                blockers,
                                step_blockers,
                                "controlled_loop_tick",
                                "git_pr_plan_file_mismatch",
                                "controlled loop tick git-pr plan file does not match embedded closeout plan",
                                expected=git_pr_plan_checksum,
                                actual=checksum_json(git_pr_plan_packet),
                            )
                        for git_pr_blocker in validate_git_pr_plan_dry_run_packet(git_pr_plan_packet):
                            controlled_loop_outcome_plan_add_existing_blocker(
                                blockers,
                                step_blockers,
                                "controlled_loop_tick",
                                dict(git_pr_blocker),
                            )

    valid = not blockers
    summary = packets.get("controlled_run_summary") if isinstance(packets.get("controlled_run_summary"), dict) else {}
    controlled_closeout = packets.get("controlled_closeout") if isinstance(packets.get("controlled_closeout"), dict) else {}
    controlled_tick = packets.get("controlled_loop_tick") if isinstance(packets.get("controlled_loop_tick"), dict) else {}
    closeout = controlled_closeout.get("closeout") if isinstance(controlled_closeout.get("closeout"), dict) else {}
    source_decision = controlled_tick.get("next_decision") if isinstance(controlled_tick.get("next_decision"), dict) else {}
    git_pr_plan = closeout.get("git_pr_plan") if isinstance(closeout.get("git_pr_plan"), dict) else None
    recommended_next_action, operator_confirmation_required, reason = controlled_loop_outcome_recommendation(
        blockers,
        source_decision=source_decision,
        git_pr_plan=git_pr_plan,
    )
    tick_task = controlled_tick.get("task") if isinstance(controlled_tick.get("task"), dict) else {}
    tick_epoch = controlled_tick.get("epoch") if isinstance(controlled_tick.get("epoch"), dict) else {}
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_OUTCOME_PLAN_SCHEMA_VERSION,
        "packet": "controlled_loop_outcome_plan",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "outcome_plan_status": "completed" if valid else "blocked",
        "reason": reason,
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": operator_confirmation_required,
        "side_effects": [],
        "recommended_next_action": recommended_next_action,
        "source_decision": source_decision,
        "task": {
            "id": tick_task.get("id"),
            "checksum": tick_task.get("checksum"),
        },
        "epoch": {
            "id": tick_epoch.get("id"),
            "closeout_status": tick_epoch.get("closeout_status") or controlled_closeout.get("closeout_status"),
            "epoch_status": tick_epoch.get("epoch_status") or controlled_closeout.get("epoch_status"),
        },
        "git_pr_plan": git_pr_plan,
        "files": {name: str(path) for name, path in packet_inputs.items()},
        "checksums": {
            name: checksum_json(packet)
            for name, packet in packets.items()
            if isinstance(packet, dict)
        },
        "steps": [
            controlled_loop_outcome_plan_step(name, path, packets.get(name), step_blockers.get(name, []))
            for name, path in packet_inputs.items()
        ],
        "blockers": blockers,
        "limitations": [
            "composes_existing_controlled_loop_outcome_evidence_only",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_continue_loop",
            "does_not_close_epoch",
            "does_not_append_audit",
            "does_not_execute_git_commands",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
        ],
    }
    emit(payload)
    return 0 if valid else 2


