def controlled_loop_runner_plan_file_matches(context_file: Path, value: Any, expected_path: Path) -> bool:
    return _closeout_paths_match(controlled_tick_context_path(context_file, value), expected_path)


def controlled_loop_runner_plan_recommendation(blockers: list[dict[str, Any]]) -> tuple[str, str]:
    if not blockers:
        return "review_controlled_runner_plan", "approved controlled runner dry-run plan is ready for review"
    blocker_codes = {blocker.get("code") for blocker in blockers}
    if "controlled_runner_manifest_approval_not_completed" in blocker_codes:
        return "fix_controlled_run_manifest_approval", "controlled run manifest approval evidence is blocked"
    if any(
        code in blocker_codes
        for code in {
            "controlled_runner_manifest_approval_evidence_missing",
            "controlled_runner_manifest_approval_packet_mismatch",
            "controlled_runner_manifest_approval_checksum_mismatch",
            "controlled_runner_manifest_approval_file_mismatch",
            "controlled_runner_operator_approval_file_missing",
            "controlled_runner_operator_approval_file_unreadable",
            "controlled_runner_operator_approval_checksum_mismatch",
            "controlled_runner_operator_approval_target_mismatch",
        }
    ):
        return "refresh_controlled_run_manifest_approval", "controlled run manifest approval evidence is stale"
    if "controlled_runner_operator_approval_verification_failed" in blocker_codes:
        return "fix_controlled_run_manifest_approval", "operator approval file no longer verifies"
    if any(
        code in blocker_codes
        for code in {
            "controlled_runner_manifest_evidence_missing",
            "controlled_runner_manifest_packet_mismatch",
            "controlled_runner_manifest_plan_not_completed",
            "controlled_runner_manifest_command_sequence_mismatch",
            "controlled_run_manifest_plan_blockers_present",
            "controlled_run_manifest_plan_steps_blocked",
            "controlled_run_manifest_plan_authority_flags_invalid",
            "controlled_run_manifest_plan_operator_confirmation_missing",
            "controlled_run_manifest_plan_command_sequence_mismatch",
        }
    ):
        return "refresh_controlled_run_manifest_plan", "controlled run manifest plan evidence is stale or blocked"
    return "inspect_controlled_runner_plan_blockers", "controlled runner plan evidence is blocked"


def controlled_loop_runner_planned_steps(command_sequence: Any) -> list[dict[str, Any]]:
    if not isinstance(command_sequence, list):
        return []
    planned_steps: list[dict[str, Any]] = []
    for item in command_sequence:
        if not isinstance(item, dict):
            continue
        planned_steps.append(
            {
                "step": item.get("step"),
                "command": item.get("command"),
                "status": "not_started",
                "evidence_files": item.get("evidence_files"),
                "execution_authority": item.get("execution_authority"),
                "allowed_side_effects_when_executed": item.get("allowed_side_effects_when_executed"),
            }
        )
    return planned_steps


def controlled_loop_runner_plan_command(args: argparse.Namespace) -> int:
    manifest_path = Path(args.controlled_run_manifest_plan_file)
    approval_path = Path(args.controlled_run_manifest_approval_file)
    manifest, manifest_blockers = read_controlled_loop_runner_plan_packet(
        manifest_path,
        code="controlled_runner_manifest_evidence_missing",
        label="controlled run manifest plan",
    )
    approval_evidence, approval_blockers = read_controlled_loop_runner_plan_packet(
        approval_path,
        code="controlled_runner_manifest_approval_evidence_missing",
        label="controlled run manifest approval",
    )
    blockers: list[dict[str, Any]] = list(manifest_blockers) + list(approval_blockers)

    if isinstance(manifest, dict):
        if (
            manifest.get("schema_version") != CONTROLLED_LOOP_RUN_MANIFEST_PLAN_SCHEMA_VERSION
            or manifest.get("packet") != "controlled_loop_run_manifest_plan"
        ):
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_packet_mismatch",
                    "controlled run manifest plan packet type is invalid",
                    expected_schema_version=CONTROLLED_LOOP_RUN_MANIFEST_PLAN_SCHEMA_VERSION,
                    actual_schema_version=manifest.get("schema_version"),
                    expected_packet="controlled_loop_run_manifest_plan",
                    actual_packet=manifest.get("packet"),
                )
            )
        if (
            manifest.get("valid") is not True
            or manifest.get("manifest_status") != "completed"
            or manifest.get("read_only") is not True
            or manifest.get("side_effects") != []
            or manifest.get("recommended_next_action") != "review_controlled_run_manifest"
        ):
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_plan_not_completed",
                    "controlled run manifest plan must be completed and ready for review",
                    valid=manifest.get("valid"),
                    manifest_status=manifest.get("manifest_status"),
                    read_only=manifest.get("read_only"),
                    side_effects=manifest.get("side_effects"),
                    recommended_next_action=manifest.get("recommended_next_action"),
                )
            )
        blockers.extend(controlled_loop_run_manifest_approval_manifest_consistency_blockers(manifest))

    if isinstance(approval_evidence, dict):
        if (
            approval_evidence.get("schema_version") != CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_SCHEMA_VERSION
            or approval_evidence.get("packet") != "controlled_loop_run_manifest_approval"
        ):
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_approval_packet_mismatch",
                    "controlled run manifest approval packet type is invalid",
                    expected_schema_version=CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_SCHEMA_VERSION,
                    actual_schema_version=approval_evidence.get("schema_version"),
                    expected_packet="controlled_loop_run_manifest_approval",
                    actual_packet=approval_evidence.get("packet"),
                )
            )
        approval_details = approval_evidence.get("approval") if isinstance(approval_evidence.get("approval"), dict) else {}
        invalid_flags = {
            flag: approval_evidence.get(flag)
            for flag in CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_FORBIDDEN_TRUE_FLAGS
            if approval_evidence.get(flag) is not False
        }
        if (
            approval_evidence.get("valid") is not True
            or approval_evidence.get("approval_status") != "completed"
            or approval_evidence.get("read_only") is not True
            or approval_evidence.get("side_effects") != []
            or approval_evidence.get("recommended_next_action") != "review_controlled_run_manifest_approval"
            or approval_evidence.get("next_controlled_action") != "review_approved_controlled_run_manifest"
            or approval_evidence.get("operator_confirmation_required") is not True
            or approval_evidence.get("blockers") != []
            or approval_details.get("state") != "approved"
            or approval_details.get("purpose") != CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_PURPOSE
            or approval_details.get("approval_purpose") != CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_PURPOSE
            or approval_details.get("signature_verified") is not True
            or approval_details.get("blocker_codes") != []
            or invalid_flags
        ):
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_approval_not_completed",
                    "controlled run manifest approval must be completed and target-bound",
                    valid=approval_evidence.get("valid"),
                    approval_status=approval_evidence.get("approval_status"),
                    read_only=approval_evidence.get("read_only"),
                    side_effects=approval_evidence.get("side_effects"),
                    recommended_next_action=approval_evidence.get("recommended_next_action"),
                    next_controlled_action=approval_evidence.get("next_controlled_action"),
                    operator_confirmation_required=approval_evidence.get("operator_confirmation_required"),
                    blocker_codes=approval_evidence.get("blockers"),
                    approval=approval_details,
                    invalid_flags=invalid_flags,
                )
            )

    manifest_checksum = checksum_json(manifest) if isinstance(manifest, dict) else None
    approval_checksum = checksum_json(approval_evidence) if isinstance(approval_evidence, dict) else None
    operator_approval_checksum: str | None = None
    if isinstance(manifest, dict) and isinstance(approval_evidence, dict):
        approval_manifest = (
            approval_evidence.get("controlled_run_manifest_plan")
            if isinstance(approval_evidence.get("controlled_run_manifest_plan"), dict)
            else {}
        )
        approval_details = approval_evidence.get("approval") if isinstance(approval_evidence.get("approval"), dict) else {}
        approval_files = approval_evidence.get("files") if isinstance(approval_evidence.get("files"), dict) else {}
        approval_checksums = approval_evidence.get("checksums") if isinstance(approval_evidence.get("checksums"), dict) else {}

        manifest_checksum_fields = {
            "controlled_run_manifest_plan.checksum": approval_manifest.get("checksum"),
            "checksums.controlled_run_manifest_plan": approval_checksums.get("controlled_run_manifest_plan"),
            "approval.target_checksum": approval_details.get("target_checksum"),
            "approval.approval_target_checksum": approval_details.get("approval_target_checksum"),
        }
        mismatched_manifest_checksum_fields = {
            field: value for field, value in manifest_checksum_fields.items() if value != manifest_checksum
        }
        if mismatched_manifest_checksum_fields:
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_approval_checksum_mismatch",
                    "controlled run manifest approval does not target the supplied manifest checksum",
                    expected=manifest_checksum,
                    actual=mismatched_manifest_checksum_fields,
                )
            )

        if approval_manifest.get("status") != "completed":
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_approval_checksum_mismatch",
                    "controlled run manifest approval does not reference a completed manifest",
                    actual=approval_manifest.get("status"),
                )
            )
        if not controlled_loop_runner_plan_file_matches(approval_path, approval_manifest.get("file"), manifest_path):
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_approval_file_mismatch",
                    "controlled run manifest approval manifest file anchor does not match supplied manifest",
                    expected=str(manifest_path),
                    actual=approval_manifest.get("file"),
                )
            )
        if not controlled_loop_runner_plan_file_matches(
            approval_path,
            approval_files.get("controlled_run_manifest_plan"),
            manifest_path,
        ):
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_approval_file_mismatch",
                    "controlled run manifest approval files.controlled_run_manifest_plan does not match supplied manifest",
                    expected=str(manifest_path),
                    actual=approval_files.get("controlled_run_manifest_plan"),
                )
            )

        operator_approval_file = approval_files.get("operator_approval")
        if not isinstance(operator_approval_file, str) or not operator_approval_file.strip():
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_operator_approval_file_missing",
                    "controlled run manifest approval must include operator approval file evidence",
                    actual=operator_approval_file,
                )
            )
        else:
            operator_approval_path = controlled_tick_context_path(approval_path, operator_approval_file)
            operator_approval, operator_approval_blockers = read_controlled_loop_runner_plan_packet(
                Path(operator_approval_path),
                code="controlled_runner_operator_approval_file_unreadable",
                label="operator approval",
            )
            blockers.extend(operator_approval_blockers)
            if isinstance(operator_approval, dict):
                operator_approval_checksum = checksum_json(operator_approval)
                operator_verification = build_operator_approval_verification_packet(
                    approval=operator_approval,
                    approval_file=Path(operator_approval_path),
                    expected_target_checksum=manifest_checksum,
                    expected_purpose=CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_PURPOSE,
                    approval_secret=operator_approval_secret_from_args(args),
                )
                if operator_verification.get("valid") is not True:
                    blockers.append(
                        controlled_loop_runner_plan_blocker(
                            "controlled_runner_operator_approval_verification_failed",
                            "operator approval file no longer verifies for the supplied controlled run manifest",
                            approval_state=operator_verification.get("approval_state"),
                            signature_verified=operator_verification.get("signature_verified"),
                            approval_blockers=operator_verification.get("blockers", []),
                        )
                    )
                operator_checksum_fields = {
                    "approval.checksum": approval_details.get("checksum"),
                    "checksums.operator_approval": approval_checksums.get("operator_approval"),
                }
                mismatched_operator_checksum_fields = {
                    field: value for field, value in operator_checksum_fields.items() if value != operator_approval_checksum
                }
                if mismatched_operator_checksum_fields:
                    blockers.append(
                        controlled_loop_runner_plan_blocker(
                            "controlled_runner_operator_approval_checksum_mismatch",
                            "controlled run manifest approval does not match the saved operator approval file",
                            expected=operator_approval_checksum,
                            actual=mismatched_operator_checksum_fields,
                        )
                    )
                if (
                    operator_approval.get("target_checksum") != manifest_checksum
                    or operator_approval.get("purpose") != CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_PURPOSE
                ):
                    blockers.append(
                        controlled_loop_runner_plan_blocker(
                            "controlled_runner_operator_approval_target_mismatch",
                            "operator approval file does not target the supplied controlled run manifest",
                            expected_target_checksum=manifest_checksum,
                            actual_target_checksum=operator_approval.get("target_checksum"),
                            expected_purpose=CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_PURPOSE,
                            actual_purpose=operator_approval.get("purpose"),
                        )
                    )

        run_manifest = manifest.get("run_manifest") if isinstance(manifest.get("run_manifest"), dict) else {}
        if run_manifest.get("command_sequence") != CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE:
            blockers.append(
                controlled_loop_runner_plan_blocker(
                    "controlled_runner_manifest_command_sequence_mismatch",
                    "controlled run manifest command sequence is invalid",
                    expected=CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE,
                    actual=run_manifest.get("command_sequence"),
                )
            )

    valid = not blockers
    recommended_next_action, reason = controlled_loop_runner_plan_recommendation(blockers)
    run_manifest = manifest.get("run_manifest") if isinstance(manifest, dict) and isinstance(manifest.get("run_manifest"), dict) else {}
    command_sequence = run_manifest.get("command_sequence")
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_RUNNER_PLAN_SCHEMA_VERSION,
        "packet": "controlled_loop_runner_plan",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "runner_plan_status": "completed" if valid else "blocked",
        "reason": reason,
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": True,
        "side_effects": [],
        "recommended_next_action": recommended_next_action,
        "next_controlled_action": "request_controlled_runner_execution_approval" if valid else recommended_next_action,
        "approved_manifest": {
            "file": str(manifest_path),
            "checksum": manifest_checksum,
            "status": manifest.get("manifest_status") if isinstance(manifest, dict) else None,
            "next_controlled_action": manifest.get("next_controlled_action") if isinstance(manifest, dict) else None,
        },
        "manifest_approval": {
            "file": str(approval_path),
            "checksum": approval_checksum,
            "status": approval_evidence.get("approval_status") if isinstance(approval_evidence, dict) else None,
            "target_checksum": (
                approval_evidence.get("approval", {}).get("target_checksum")
                if isinstance(approval_evidence, dict) and isinstance(approval_evidence.get("approval"), dict)
                else None
            ),
            "approval_target_checksum": (
                approval_evidence.get("approval", {}).get("approval_target_checksum")
                if isinstance(approval_evidence, dict) and isinstance(approval_evidence.get("approval"), dict)
                else None
            ),
            "operator_approval_checksum": operator_approval_checksum,
        },
        "runner_plan": {
            "mode": "dry_run",
            "manifest_checksum": manifest_checksum,
            "approval_checksum": approval_checksum,
            "evidence_files": run_manifest.get("evidence_files") if isinstance(run_manifest, dict) else {},
            "checksums": run_manifest.get("checksums") if isinstance(run_manifest, dict) else {},
            "planned_command_sequence": command_sequence if isinstance(command_sequence, list) else [],
            "planned_steps": controlled_loop_runner_planned_steps(command_sequence),
        },
        "files": {
            "controlled_run_manifest_plan": str(manifest_path),
            "controlled_run_manifest_approval": str(approval_path),
        },
        "checksums": {
            "controlled_run_manifest_plan": manifest_checksum,
            "controlled_run_manifest_approval": approval_checksum,
            "operator_approval": operator_approval_checksum,
        },
        "blockers": blockers,
        "limitations": [
            "plans_approved_controlled_loop_run_manifest_only",
            "dry_run_only",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_continue_loop",
            "does_not_start_epoch",
            "does_not_close_epoch",
            "does_not_append_audit",
            "does_not_execute_git_commands",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_SCHEMA_VERSION = "controlled-loop-runner-execution-approval.v1"
CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE = "controlled_loop_runner_execution"


def controlled_loop_runner_execution_approval_blocker(
    code: str,
    message: str,
    **extra: Any,
) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_runner_execution_approval_packet(
    path: Path,
    *,
    code: str,
    label: str,
) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [
            controlled_loop_runner_execution_approval_blocker(
                code,
                f"{label} could not be read as JSON",
                path=str(path),
                error=str(exc),
            )
        ]
    if not isinstance(packet, dict):
        return None, [
            controlled_loop_runner_execution_approval_blocker(
                code,
                f"{label} must be a JSON object",
                path=str(path),
            )
        ]
    return packet, []


def controlled_loop_runner_execution_approval_recommendation(
    blockers: list[dict[str, Any]],
) -> tuple[str, str]:
    if not blockers:
        return "review_controlled_runner_execution_approval", "controlled runner execution approval accepted"
    blocker_codes = {blocker.get("code") for blocker in blockers}
    if any(isinstance(code, str) and code.startswith("controlled_runner_plan_") for code in blocker_codes):
        return "refresh_controlled_runner_plan", "controlled runner plan evidence is stale or blocked"
    if any(isinstance(code, str) and code.startswith("operator_approval_") for code in blocker_codes):
        return "fix_controlled_runner_execution_approval", "controlled runner execution approval evidence is blocked"
    return "inspect_controlled_runner_execution_approval_blockers", "controlled runner execution approval is blocked"


def controlled_loop_runner_execution_approval_plan_blockers(
    runner_plan: dict[str, Any],
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if (
        runner_plan.get("valid") is not True
        or runner_plan.get("runner_plan_status") != "completed"
        or runner_plan.get("read_only") is not True
        or runner_plan.get("side_effects") != []
        or runner_plan.get("recommended_next_action") != "review_controlled_runner_plan"
        or runner_plan.get("next_controlled_action") != "request_controlled_runner_execution_approval"
        or runner_plan.get("operator_confirmation_required") is not True
        or runner_plan.get("blockers") != []
    ):
        blockers.append(
            controlled_loop_runner_execution_approval_blocker(
                "controlled_runner_plan_not_completed",
                "controlled runner plan must be completed and ready for execution approval",
                valid=runner_plan.get("valid"),
                runner_plan_status=runner_plan.get("runner_plan_status"),
                read_only=runner_plan.get("read_only"),
                side_effects=runner_plan.get("side_effects"),
                recommended_next_action=runner_plan.get("recommended_next_action"),
                next_controlled_action=runner_plan.get("next_controlled_action"),
                operator_confirmation_required=runner_plan.get("operator_confirmation_required"),
                blocker_codes=runner_plan.get("blockers"),
            )
        )

    invalid_flags = {
        flag: runner_plan.get(flag)
        for flag in CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_FORBIDDEN_TRUE_FLAGS
        if runner_plan.get(flag) is not False
    }
    if invalid_flags:
        blockers.append(
            controlled_loop_runner_execution_approval_blocker(
                "controlled_runner_plan_authority_flags_invalid",
                "controlled runner plan must not report started authority flags",
                flags=invalid_flags,
            )
        )

    plan_details = runner_plan.get("runner_plan") if isinstance(runner_plan.get("runner_plan"), dict) else {}
    command_sequence = plan_details.get("planned_command_sequence")
    if command_sequence != CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE:
        blockers.append(
            controlled_loop_runner_execution_approval_blocker(
                "controlled_runner_plan_command_sequence_mismatch",
                "controlled runner plan command sequence is invalid",
                expected=CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE,
                actual=command_sequence,
            )
        )
    if plan_details.get("mode") != "dry_run":
        blockers.append(
            controlled_loop_runner_execution_approval_blocker(
                "controlled_runner_plan_mode_invalid",
                "controlled runner plan must remain in dry-run mode",
                actual=plan_details.get("mode"),
            )
        )

    planned_steps = plan_details.get("planned_steps")
    expected_planned_steps = controlled_loop_runner_planned_steps(CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE)
    if planned_steps != expected_planned_steps:
        blockers.append(
            controlled_loop_runner_execution_approval_blocker(
                "controlled_runner_plan_steps_mismatch",
                "controlled runner plan steps must match the approved not-started command sequence",
                expected=expected_planned_steps,
                actual=planned_steps,
            )
        )
    return blockers


def controlled_loop_runner_execution_approval_command(args: argparse.Namespace) -> int:
    runner_plan_path = Path(args.controlled_loop_runner_plan_file)
    approval_path = Path(args.approval_file)
    runner_plan, runner_plan_blockers = read_controlled_loop_runner_execution_approval_packet(
        runner_plan_path,
        code="controlled_runner_plan_evidence_missing",
        label="controlled runner plan",
    )
    blockers: list[dict[str, Any]] = list(runner_plan_blockers)

    if isinstance(runner_plan, dict):
        if (
            runner_plan.get("schema_version") != CONTROLLED_LOOP_RUNNER_PLAN_SCHEMA_VERSION
            or runner_plan.get("packet") != "controlled_loop_runner_plan"
        ):
            blockers.append(
                controlled_loop_runner_execution_approval_blocker(
                    "controlled_runner_plan_packet_mismatch",
                    "controlled runner plan packet type is invalid",
                    expected_schema_version=CONTROLLED_LOOP_RUNNER_PLAN_SCHEMA_VERSION,
                    actual_schema_version=runner_plan.get("schema_version"),
                    expected_packet="controlled_loop_runner_plan",
                    actual_packet=runner_plan.get("packet"),
                )
            )
        blockers.extend(controlled_loop_runner_execution_approval_plan_blockers(runner_plan))

    runner_plan_checksum = checksum_json(runner_plan) if isinstance(runner_plan, dict) else "sha256:" + "0" * 64
    approval_packet, approval_read_blockers = read_controlled_loop_runner_execution_approval_packet(
        approval_path,
        code="operator_approval_file_unreadable",
        label="operator approval",
    )
    blockers.extend(approval_read_blockers)
    approval_verification = build_operator_approval_verification_packet(
        approval=approval_packet,
        approval_file=approval_path,
        expected_target_checksum=runner_plan_checksum,
        expected_purpose=CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE,
        approval_secret=operator_approval_secret_from_args(args),
    )
    blockers.extend(approval_verification.get("blockers", []))

    valid = not blockers
    recommended_next_action, reason = controlled_loop_runner_execution_approval_recommendation(blockers)
    approval_checksum = checksum_json(approval_packet) if isinstance(approval_packet, dict) else None
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_SCHEMA_VERSION,
        "packet": "controlled_loop_runner_execution_approval",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "approval_status": "completed" if valid else "blocked",
        "reason": reason,
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": True,
        "side_effects": [],
        "recommended_next_action": recommended_next_action,
        "next_controlled_action": "review_approved_controlled_runner_execution" if valid else recommended_next_action,
        "controlled_loop_runner_plan": {
            "file": str(runner_plan_path),
            "checksum": runner_plan_checksum if isinstance(runner_plan, dict) else None,
            "status": runner_plan.get("runner_plan_status") if isinstance(runner_plan, dict) else None,
            "next_controlled_action": runner_plan.get("next_controlled_action") if isinstance(runner_plan, dict) else None,
        },
        "approval": {
            "state": approval_verification.get("approval_state"),
            "file": str(approval_path),
            "checksum": approval_checksum,
            "target_checksum": runner_plan_checksum if isinstance(runner_plan, dict) else None,
            "approval_target_checksum": approval_verification.get("approval_target_checksum"),
            "purpose": CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE,
            "approval_purpose": approval_verification.get("approval_purpose"),
            "operator_id": approval_verification.get("operator_id"),
            "key_id": approval_verification.get("key_id"),
            "issued_at": approval_verification.get("issued_at"),
            "expires_at": approval_verification.get("expires_at"),
            "signature_verified": approval_verification.get("signature_verified"),
            "blocker_codes": [blocker["code"] for blocker in approval_verification.get("blockers", [])],
        },
        "files": {
            "controlled_loop_runner_plan": str(runner_plan_path),
            "operator_approval": str(approval_path),
        },
        "checksums": {
            "controlled_loop_runner_plan": runner_plan_checksum if isinstance(runner_plan, dict) else None,
            "operator_approval": approval_checksum,
        },
        "blockers": blockers,
        "limitations": [
            "approves_existing_controlled_loop_runner_plan_only",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_retry_executor",
            "does_not_continue_loop",
            "does_not_start_epoch",
            "does_not_close_epoch",
            "does_not_append_audit",
            "does_not_execute_git_commands",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_RUNNER_DRY_RUN_SCHEMA_VERSION = "controlled-loop-runner-dry-run.v1"

CONTROLLED_LOOP_RUNNER_DRY_RUN_NON_EXECUTION_GUARANTEES = [
    "does_not_start_runner",
    "does_not_invoke_executor",
    "does_not_retry_executor",
    "does_not_continue_loop",
    "does_not_write_git_or_github_state",
    "does_not_merge",
    "does_not_release",
    "does_not_assign_roles",
    "does_not_schedule_agents",
]


def controlled_loop_runner_dry_run_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def read_controlled_loop_runner_dry_run_packet(
    path: Path,
    *,
    code: str,
    label: str,
) -> tuple[Any | None, list[dict[str, Any]]]:
    try:
        packet = read_json(path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [
            controlled_loop_runner_dry_run_blocker(
                code,
                f"{label} could not be read as JSON",
                path=str(path),
                error=str(exc),
            )
        ]
    if not isinstance(packet, dict):
        return None, [controlled_loop_runner_dry_run_blocker(code, f"{label} must be a JSON object", path=str(path))]
    return packet, []


def controlled_loop_runner_dry_run_recommendation(
    blockers: list[dict[str, Any]],
) -> tuple[str, str]:
    if not blockers:
        return "review_controlled_runner_dry_run", "controlled runner dry-run evidence is ready for review"
    blocker_codes = {blocker.get("code") for blocker in blockers}
    if any(isinstance(code, str) and code.startswith("controlled_runner_plan_") for code in blocker_codes):
        return "refresh_controlled_runner_plan", "controlled runner plan evidence is stale or blocked"
    if any(
        isinstance(code, str) and code.startswith("controlled_runner_dry_run_execution_approval_")
        for code in blocker_codes
    ):
        return "refresh_controlled_runner_execution_approval", "controlled runner execution approval is stale or blocked"
    if any(
        isinstance(code, str)
        and (code.startswith("operator_approval_") or code.startswith("controlled_runner_dry_run_operator_approval_"))
        for code in blocker_codes
    ):
        return "fix_controlled_runner_execution_approval", "controlled runner operator approval evidence is blocked"
    return "inspect_controlled_runner_dry_run_blockers", "controlled runner dry run is blocked"


def controlled_loop_runner_dry_run_stages(runner_plan: dict[str, Any] | None) -> list[dict[str, Any]]:
    plan_details = runner_plan.get("runner_plan") if isinstance(runner_plan, dict) and isinstance(runner_plan.get("runner_plan"), dict) else {}
    planned_steps = plan_details.get("planned_steps")
    if not isinstance(planned_steps, list):
        return []

    stages: list[dict[str, Any]] = []
    for step in planned_steps:
        if not isinstance(step, dict):
            continue
        stages.append(
            {
                "step": step.get("step"),
                "command": step.get("command"),
                "status": "would_process",
                "evidence_files": step.get("evidence_files"),
                "execution_authority": step.get("execution_authority"),
                "allowed_side_effects_when_executed": step.get("allowed_side_effects_when_executed"),
                "runner_started": False,
                "executor_started": False,
                "side_effects": [],
                "guarantees": [
                    "dry_run_only",
                    "no_runner_process_started",
                    "no_executor_process_started",
                    "no_state_written",
                ],
            }
        )
    return stages


def controlled_loop_runner_dry_run_command(args: argparse.Namespace) -> int:
    runner_plan_path = Path(args.controlled_loop_runner_plan_file)
    execution_approval_path = Path(args.controlled_loop_runner_execution_approval_file)
    runner_plan, runner_plan_blockers = read_controlled_loop_runner_dry_run_packet(
        runner_plan_path,
        code="controlled_runner_plan_evidence_missing",
        label="controlled runner plan",
    )
    execution_approval, execution_approval_blockers = read_controlled_loop_runner_dry_run_packet(
        execution_approval_path,
        code="controlled_runner_dry_run_execution_approval_evidence_missing",
        label="controlled runner execution approval",
    )
    blockers: list[dict[str, Any]] = list(runner_plan_blockers) + list(execution_approval_blockers)

    if isinstance(runner_plan, dict):
        if (
            runner_plan.get("schema_version") != CONTROLLED_LOOP_RUNNER_PLAN_SCHEMA_VERSION
            or runner_plan.get("packet") != "controlled_loop_runner_plan"
        ):
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_plan_packet_mismatch",
                    "controlled runner plan packet type is invalid",
                    expected_schema_version=CONTROLLED_LOOP_RUNNER_PLAN_SCHEMA_VERSION,
                    actual_schema_version=runner_plan.get("schema_version"),
                    expected_packet="controlled_loop_runner_plan",
                    actual_packet=runner_plan.get("packet"),
                )
            )
        blockers.extend(controlled_loop_runner_execution_approval_plan_blockers(runner_plan))

    if isinstance(execution_approval, dict):
        if (
            execution_approval.get("schema_version") != CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_SCHEMA_VERSION
            or execution_approval.get("packet") != "controlled_loop_runner_execution_approval"
        ):
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_packet_mismatch",
                    "controlled runner execution approval packet type is invalid",
                    expected_schema_version=CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_SCHEMA_VERSION,
                    actual_schema_version=execution_approval.get("schema_version"),
                    expected_packet="controlled_loop_runner_execution_approval",
                    actual_packet=execution_approval.get("packet"),
                )
            )

        invalid_flags = {
            flag: execution_approval.get(flag)
            for flag in CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_FORBIDDEN_TRUE_FLAGS
            if execution_approval.get(flag) is not False
        }
        if invalid_flags:
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_authority_flags_invalid",
                    "controlled runner execution approval must not report started authority flags",
                    flags=invalid_flags,
                )
            )
        if (
            execution_approval.get("valid") is not True
            or execution_approval.get("approval_status") != "completed"
            or execution_approval.get("read_only") is not True
            or execution_approval.get("side_effects") != []
            or execution_approval.get("recommended_next_action") != "review_controlled_runner_execution_approval"
            or execution_approval.get("next_controlled_action") != "review_approved_controlled_runner_execution"
            or execution_approval.get("operator_confirmation_required") is not True
            or execution_approval.get("blockers") != []
        ):
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_not_completed",
                    "controlled runner execution approval must be completed and ready for dry-run review",
                    valid=execution_approval.get("valid"),
                    approval_status=execution_approval.get("approval_status"),
                    read_only=execution_approval.get("read_only"),
                    side_effects=execution_approval.get("side_effects"),
                    recommended_next_action=execution_approval.get("recommended_next_action"),
                    next_controlled_action=execution_approval.get("next_controlled_action"),
                    operator_confirmation_required=execution_approval.get("operator_confirmation_required"),
                    blocker_codes=execution_approval.get("blockers"),
                )
            )

    runner_plan_checksum = checksum_json(runner_plan) if isinstance(runner_plan, dict) else None
    execution_approval_checksum = checksum_json(execution_approval) if isinstance(execution_approval, dict) else None
    operator_approval_path: Path | None = None
    operator_approval_checksum: str | None = None
    approval_verification: dict[str, Any] = {
        "approval_state": None,
        "approval_target_checksum": None,
        "approval_purpose": None,
        "operator_id": None,
        "key_id": None,
        "issued_at": None,
        "expires_at": None,
        "signature_verified": False,
        "blockers": [],
    }

    if isinstance(runner_plan, dict) and isinstance(execution_approval, dict):
        approval_plan = (
            execution_approval.get("controlled_loop_runner_plan")
            if isinstance(execution_approval.get("controlled_loop_runner_plan"), dict)
            else {}
        )
        approval_details = execution_approval.get("approval") if isinstance(execution_approval.get("approval"), dict) else {}
        approval_files = execution_approval.get("files") if isinstance(execution_approval.get("files"), dict) else {}
        approval_checksums = execution_approval.get("checksums") if isinstance(execution_approval.get("checksums"), dict) else {}

        runner_plan_checksum_fields = {
            "controlled_loop_runner_plan.checksum": approval_plan.get("checksum"),
            "checksums.controlled_loop_runner_plan": approval_checksums.get("controlled_loop_runner_plan"),
            "approval.target_checksum": approval_details.get("target_checksum"),
            "approval.approval_target_checksum": approval_details.get("approval_target_checksum"),
        }
        mismatched_runner_plan_checksum_fields = {
            field: value for field, value in runner_plan_checksum_fields.items() if value != runner_plan_checksum
        }
        if mismatched_runner_plan_checksum_fields:
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_plan_checksum_mismatch",
                    "controlled runner execution approval does not target the supplied runner plan checksum",
                    expected=runner_plan_checksum,
                    actual=mismatched_runner_plan_checksum_fields,
                )
            )
        if approval_plan.get("status") != "completed":
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_plan_checksum_mismatch",
                    "controlled runner execution approval does not reference a completed runner plan",
                    actual=approval_plan.get("status"),
                )
            )
        if not controlled_loop_runner_plan_file_matches(execution_approval_path, approval_plan.get("file"), runner_plan_path):
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_file_mismatch",
                    "controlled runner execution approval runner-plan file anchor does not match supplied runner plan",
                    expected=str(runner_plan_path),
                    actual=approval_plan.get("file"),
                )
            )
        if not controlled_loop_runner_plan_file_matches(
            execution_approval_path,
            approval_files.get("controlled_loop_runner_plan"),
            runner_plan_path,
        ):
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_file_mismatch",
                    "controlled runner execution approval files.controlled_loop_runner_plan does not match supplied runner plan",
                    expected=str(runner_plan_path),
                    actual=approval_files.get("controlled_loop_runner_plan"),
                )
            )

        if (
            approval_details.get("state") != "approved"
            or approval_details.get("purpose") != CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE
            or approval_details.get("approval_purpose") != CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE
            or approval_details.get("signature_verified") is not True
            or approval_details.get("blocker_codes") != []
        ):
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_execution_approval_approval_mismatch",
                    "controlled runner execution approval must carry accepted approval identity evidence",
                    approval=approval_details,
                )
            )

        operator_approval_file = approval_files.get("operator_approval")
        if not isinstance(operator_approval_file, str) or not operator_approval_file.strip():
            blockers.append(
                controlled_loop_runner_dry_run_blocker(
                    "controlled_runner_dry_run_operator_approval_file_missing",
                    "controlled runner execution approval must include operator approval file evidence",
                    actual=operator_approval_file,
                )
            )
        else:
            operator_approval_path = Path(controlled_tick_context_path(execution_approval_path, operator_approval_file))
            if not controlled_loop_runner_plan_file_matches(
                execution_approval_path,
                approval_details.get("file"),
                operator_approval_path,
            ):
                blockers.append(
                    controlled_loop_runner_dry_run_blocker(
                        "controlled_runner_dry_run_operator_approval_file_mismatch",
                        "controlled runner execution approval approval.file anchor does not match saved operator approval",
                        expected=str(operator_approval_path),
                        actual=approval_details.get("file"),
                    )
                )
            operator_approval, operator_approval_blockers = read_controlled_loop_runner_dry_run_packet(
                operator_approval_path,
                code="controlled_runner_dry_run_operator_approval_file_unreadable",
                label="operator approval",
            )
            blockers.extend(operator_approval_blockers)
            if isinstance(operator_approval, dict):
                operator_approval_checksum = checksum_json(operator_approval)
                approval_verification = build_operator_approval_verification_packet(
                    approval=operator_approval,
                    approval_file=operator_approval_path,
                    expected_target_checksum=runner_plan_checksum,
                    expected_purpose=CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE,
                    approval_secret=operator_approval_secret_from_args(args),
                )
                blockers.extend(approval_verification.get("blockers", []))
                operator_checksum_fields = {
                    "approval.checksum": approval_details.get("checksum"),
                    "checksums.operator_approval": approval_checksums.get("operator_approval"),
                }
                mismatched_operator_checksum_fields = {
                    field: value for field, value in operator_checksum_fields.items() if value != operator_approval_checksum
                }
                if mismatched_operator_checksum_fields:
                    blockers.append(
                        controlled_loop_runner_dry_run_blocker(
                            "controlled_runner_dry_run_operator_approval_checksum_mismatch",
                            "controlled runner execution approval does not match the saved operator approval file",
                            expected=operator_approval_checksum,
                            actual=mismatched_operator_checksum_fields,
                        )
                    )
                if (
                    operator_approval.get("target_checksum") != runner_plan_checksum
                    or operator_approval.get("purpose") != CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE
                ):
                    blockers.append(
                        controlled_loop_runner_dry_run_blocker(
                            "controlled_runner_dry_run_operator_approval_target_mismatch",
                            "operator approval file does not target the supplied controlled runner plan",
                            expected_target_checksum=runner_plan_checksum,
                            actual_target_checksum=operator_approval.get("target_checksum"),
                            expected_purpose=CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE,
                            actual_purpose=operator_approval.get("purpose"),
                        )
                    )

    valid = not blockers
    recommended_next_action, reason = controlled_loop_runner_dry_run_recommendation(blockers)
    runner_plan_details = runner_plan.get("runner_plan") if isinstance(runner_plan, dict) and isinstance(runner_plan.get("runner_plan"), dict) else {}
    command_sequence = runner_plan_details.get("planned_command_sequence")
    payload = {
        "protocol_version": PROTOCOL_VERSION,
        "schema_version": CONTROLLED_LOOP_RUNNER_DRY_RUN_SCHEMA_VERSION,
        "packet": "controlled_loop_runner_dry_run",
        "generated_at": utc_now(),
        "read_only": True,
        "valid": valid,
        "runner_dry_run_status": "completed" if valid else "blocked",
        "reason": reason,
        "runner_started": False,
        "executor_started": False,
        "epoch_started": False,
        "pr_action_started": False,
        "github_write_started": False,
        "merge_started": False,
        "release_started": False,
        "package_publication_started": False,
        "role_assignment_started": False,
        "agent_scheduling_started": False,
        "loop_continuation_started": False,
        "operator_confirmation_required": True,
        "side_effects": [],
        "recommended_next_action": recommended_next_action,
        "next_controlled_action": "stop_after_controlled_runner_dry_run" if valid else recommended_next_action,
        "controlled_loop_runner_plan": {
            "file": str(runner_plan_path),
            "checksum": runner_plan_checksum,
            "status": runner_plan.get("runner_plan_status") if isinstance(runner_plan, dict) else None,
            "next_controlled_action": runner_plan.get("next_controlled_action") if isinstance(runner_plan, dict) else None,
        },
        "controlled_loop_runner_execution_approval": {
            "file": str(execution_approval_path),
            "checksum": execution_approval_checksum,
            "status": execution_approval.get("approval_status") if isinstance(execution_approval, dict) else None,
            "next_controlled_action": execution_approval.get("next_controlled_action") if isinstance(execution_approval, dict) else None,
        },
        "approval": {
            "state": approval_verification.get("approval_state"),
            "file": str(operator_approval_path) if operator_approval_path is not None else None,
            "checksum": operator_approval_checksum,
            "target_checksum": runner_plan_checksum,
            "approval_target_checksum": approval_verification.get("approval_target_checksum"),
            "purpose": CONTROLLED_LOOP_RUNNER_EXECUTION_APPROVAL_PURPOSE,
            "approval_purpose": approval_verification.get("approval_purpose"),
            "operator_id": approval_verification.get("operator_id"),
            "key_id": approval_verification.get("key_id"),
            "issued_at": approval_verification.get("issued_at"),
            "expires_at": approval_verification.get("expires_at"),
            "signature_verified": approval_verification.get("signature_verified"),
            "blocker_codes": [blocker["code"] for blocker in approval_verification.get("blockers", [])],
        },
        "runner_dry_run": {
            "mode": "dry_run",
            "runner_plan_checksum": runner_plan_checksum,
            "execution_approval_checksum": execution_approval_checksum,
            "planned_command_sequence": command_sequence if isinstance(command_sequence, list) else [],
            "stages": controlled_loop_runner_dry_run_stages(runner_plan if isinstance(runner_plan, dict) else None),
        },
        "files": {
            "controlled_loop_runner_plan": str(runner_plan_path),
            "controlled_loop_runner_execution_approval": str(execution_approval_path),
            "operator_approval": str(operator_approval_path) if operator_approval_path is not None else None,
        },
        "checksums": {
            "controlled_loop_runner_plan": runner_plan_checksum,
            "controlled_loop_runner_execution_approval": execution_approval_checksum,
            "operator_approval": operator_approval_checksum,
        },
        "blockers": blockers,
        "non_execution_guarantees": CONTROLLED_LOOP_RUNNER_DRY_RUN_NON_EXECUTION_GUARANTEES,
        "limitations": [
            "dry_run_only",
            "consumes_approved_controlled_loop_runner_plan_only",
            "consumes_approved_controlled_loop_runner_execution_approval_only",
            "does_not_start_runner",
            "does_not_start_executor",
            "does_not_invoke_executor",
            "does_not_retry_executor",
            "does_not_continue_loop",
            "does_not_start_epoch",
            "does_not_close_epoch",
            "does_not_append_audit",
            "does_not_execute_git_commands",
            "does_not_call_github",
            "does_not_create_branch",
            "does_not_commit",
            "does_not_push",
            "does_not_create_pr",
            "does_not_merge",
            "does_not_release",
            "does_not_publish_packages",
            "does_not_assign_roles",
            "does_not_schedule_agents",
        ],
    }
    emit(payload)
    return 0 if valid else 2


CONTROLLED_LOOP_RUNNER_START_READINESS_SCHEMA_VERSION = "controlled-loop-runner-start-readiness.v1"


def controlled_loop_runner_start_readiness_blocker(code: str, message: str, **extra: Any) -> dict[str, Any]:
    blocker = {"code": code, "message": message}
    blocker.update(extra)
    return blocker


def controlled_loop_runner_start_readiness_recommendation(
    blockers: list[dict[str, Any]],
) -> tuple[str, str]:
    if not blockers:
        return "review_controlled_runner_start_readiness", "controlled runner start readiness is ready for review"
    blocker_codes = {blocker.get("code") for blocker in blockers}
    if any(
        isinstance(code, str) and code.startswith("controlled_runner_start_readiness_dry_run_")
        for code in blocker_codes
    ):
        return "refresh_controlled_runner_dry_run", "controlled runner dry-run evidence is stale or blocked"
    if blocker_codes & {
        "controlled_runner_start_readiness_authority_flags_invalid",
        "controlled_runner_start_readiness_non_execution_guarantees_missing",
        "controlled_runner_start_readiness_stage_malformed",
        "controlled_runner_start_readiness_stage_not_would_process",
        "controlled_runner_start_readiness_stage_sequence_mismatch",
    }:
        return "refresh_controlled_runner_dry_run", "controlled runner dry-run evidence is malformed"
    if any(
        isinstance(code, str)
        and (
            code.startswith("controlled_runner_start_readiness_runner_plan_")
            or code.startswith("controlled_runner_start_readiness_execution_approval_")
        )
        for code in blocker_codes
    ):
        return "refresh_controlled_runner_dry_run", "controlled runner start-readiness anchors are stale"
    return "inspect_controlled_runner_start_readiness_blockers", "controlled runner start readiness is blocked"


def controlled_loop_runner_start_readiness_runner_plan_blockers(
    runner_plan: dict[str, Any],
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    if (
        runner_plan.get("schema_version") != CONTROLLED_LOOP_RUNNER_PLAN_SCHEMA_VERSION
        or runner_plan.get("packet") != "controlled_loop_runner_plan"
    ):
        blockers.append(
            controlled_loop_runner_start_readiness_blocker(
                "controlled_runner_start_readiness_runner_plan_packet_mismatch",
                "controlled runner plan packet type is invalid",
                expected_schema_version=CONTROLLED_LOOP_RUNNER_PLAN_SCHEMA_VERSION,
                actual_schema_version=runner_plan.get("schema_version"),
                expected_packet="controlled_loop_runner_plan",
                actual_packet=runner_plan.get("packet"),
            )
        )

    if (
        runner_plan.get("valid") is not True
        or runner_plan.get("runner_plan_status") != "completed"
        or runner_plan.get("read_only") is not True
        or runner_plan.get("side_effects") != []
        or runner_plan.get("recommended_next_action") != "review_controlled_runner_plan"
        or runner_plan.get("next_controlled_action") != "request_controlled_runner_execution_approval"
        or runner_plan.get("operator_confirmation_required") is not True
        or runner_plan.get("blockers") != []
    ):
        blockers.append(
            controlled_loop_runner_start_readiness_blocker(
                "controlled_runner_start_readiness_runner_plan_not_completed",
                "controlled runner plan must be completed before runner start readiness",
                valid=runner_plan.get("valid"),
                runner_plan_status=runner_plan.get("runner_plan_status"),
                read_only=runner_plan.get("read_only"),
                side_effects=runner_plan.get("side_effects"),
                recommended_next_action=runner_plan.get("recommended_next_action"),
                next_controlled_action=runner_plan.get("next_controlled_action"),
                operator_confirmation_required=runner_plan.get("operator_confirmation_required"),
                blocker_codes=runner_plan.get("blockers"),
            )
        )

    invalid_flags = {
        flag: runner_plan.get(flag)
        for flag in CONTROLLED_LOOP_RUN_MANIFEST_APPROVAL_FORBIDDEN_TRUE_FLAGS
        if runner_plan.get(flag) is not False
    }
    if invalid_flags:
        blockers.append(
            controlled_loop_runner_start_readiness_blocker(
                "controlled_runner_start_readiness_runner_plan_authority_flags_invalid",
                "controlled runner plan must not report started authority flags",
                flags=invalid_flags,
            )
        )

    plan_details = runner_plan.get("runner_plan") if isinstance(runner_plan.get("runner_plan"), dict) else {}
    command_sequence = plan_details.get("planned_command_sequence")
    if command_sequence != CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE:
        blockers.append(
            controlled_loop_runner_start_readiness_blocker(
                "controlled_runner_start_readiness_runner_plan_command_sequence_mismatch",
                "controlled runner plan command sequence is invalid",
                expected=CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE,
                actual=command_sequence,
            )
        )
    if plan_details.get("mode") != "dry_run":
        blockers.append(
            controlled_loop_runner_start_readiness_blocker(
                "controlled_runner_start_readiness_runner_plan_mode_invalid",
                "controlled runner plan must remain in dry-run mode",
                actual=plan_details.get("mode"),
            )
        )

    planned_steps = plan_details.get("planned_steps")
    expected_planned_steps = controlled_loop_runner_planned_steps(CONTROLLED_LOOP_RUN_MANIFEST_COMMAND_SEQUENCE)
    if planned_steps != expected_planned_steps:
        blockers.append(
            controlled_loop_runner_start_readiness_blocker(
                "controlled_runner_start_readiness_runner_plan_steps_mismatch",
                "controlled runner plan steps must match the approved not-started command sequence",
                expected=expected_planned_steps,
                actual=planned_steps,
            )
        )
    return blockers


